  vec3 viewNormal = normalize(normalMatrix * aNormal);
  vec3 viewDirection = normalize(-viewPosition.xyz);
  vec3 lightDirection = normalize(vec3(-0.55, 0.42, 0.72));
  float diffuse = max(dot(viewNormal, lightDirection), 0.0);
  float backLight = max(dot(-viewNormal, lightDirection), 0.0);
  float rimBase = 1.0 - max(dot(viewNormal, viewDirection), 0.0);
  float rim = rimBase * rimBase;
  float depthGlow = smoothstep(4.2, 1.1, -viewPosition.z);
  float assemblyNoise = (aSeed - 0.5) * 0.18;
  float assembly = smoothstep(0.0, 1.0, clamp(uAssemblyProgress + assemblyNoise, 0.0, 1.0));

  vec4 modelClipPosition = projectionMatrix * viewPosition;
