    float noiseX = sin(uTime * 0.86 + aSeed * 43.19);
    float noiseY = cos(uTime * 1.12 + aSeed * 31.41);
    spreadClipPosition.xy += vec2(noiseX, noiseY) * modelClipPosition.w * 0.035 * unsettled * unsettled;
