  gl_Position = mix(spreadClipPosition, modelClipPosition, assembly);
  float clipY = gl_Position.y / gl_Position.w;
  float topFade = 1.0 - smoothstep(0.68, 0.98, clipY);
  float edgeFade = mix(topFade, 1.0, assembly);
  float highlightSize = 1.0 + aHighlight * (1.8 + aSeed * 0.7);
  float assemblySize = mix(mix(1.85, 1.0, assembly), 1.0, aHighlight);

  gl_PointSize = uParticleSize * assemblySize * (1.0 + rim * 0.16 + depthGlow * 0.08) * aPointScale * highlightSize;
  vAlpha = (0.13 + depthGlow * 0.06 + rim * 0.05) * aShade * mix(0.42, 1.0, assembly) * (1.0 + aHighlight * 1.35) * edgeFade;
  vGlow = clamp((rim * 0.62 + backLight * 0.34 + depthGlow * 0.22 + aHighlight * 0.72) * aShade, 0.0, 1.0);
  vHighlight = aHighlight;
  vShade = clamp((diffuse * 0.7 + backLight * 0.28 + rim * 0.32 + depthGlow * 0.26 + aHighlight * 0.48) * aShade, 0.12, 1.36);
