float smoothNoise(vec3 position) {
  vec3 cell = floor(position);
  vec3 localPosition = fract(position);
  vec3 blend =
    localPosition * localPosition * localPosition *
    (localPosition * (localPosition * 6.0 - 15.0) + 10.0);

  float nearBottom = mix(
    mix(hash(cell), hash(cell + vec3(1.0, 0.0, 0.0)), blend.x),
    mix(
      hash(cell + vec3(0.0, 1.0, 0.0)),
      hash(cell + vec3(1.0, 1.0, 0.0)),
      blend.x
    ),
    blend.y
  );
  float farBottom = mix(
    mix(
      hash(cell + vec3(0.0, 0.0, 1.0)),
      hash(cell + vec3(1.0, 0.0, 1.0)),
      blend.x
    ),
    mix(
      hash(cell + vec3(0.0, 1.0, 1.0)),
      hash(cell + vec3(1.0, 1.0, 1.0)),
      blend.x
    ),
    blend.y
