float noise(vec2 point) {
  vec2 cell = floor(point);
  vec2 local = fract(point);
  vec2 curve = local * local * (3.0 - 2.0 * local);

  float bottomLeft = random(cell);
  float bottomRight = random(cell + vec2(1.0, 0.0));
  float topLeft = random(cell + vec2(0.0, 1.0));
  float topRight = random(cell + vec2(1.0, 1.0));

  return mix(
    mix(bottomLeft, bottomRight, curve.x),
    mix(topLeft, topRight, curve.x),
    curve.y
  );
}

float fbm(vec2 point) {
  float value = 0.0;
  float amplitude = 0.52;
  mat2 rotation = mat2(0.80, -0.60, 0.60, 0.80);

  for (int octave = 0; octave < FBM_OCTAVES; octave++) {
    value += amplitude * noise(point);
    point = rotation * point * 2.03 + vec2(7.1, 3.7);
    amplitude *= 0.5;
  }

  return value;
}

void main() {
  vec2 uv = v_uv;
  float aspect = min(u_resolution.x / max(u_resolution.y, 1.0), 3.0);
  float motionTime = u_time * max(u_speed, 0.0);

  vec2 point = vec2(uv.x * (1.12 + aspect * 0.16), uv.y * 1.08);
  vec2 drift = vec2(
    motionTime * 0.34 + sin(motionTime * 0.41) * 0.12,
    -motionTime * 0.07 + cos(motionTime * 0.29) * 0.10
  );

  vec2 firstWarp = vec2(
    fbm(point * 1.05 + drift),
    fbm(point * 1.05 + drift + vec2(4.8, 1.7))
  );
  float secondField = fbm(
    point * 1.45 + firstWarp * (1.25 * u_warp) + vec2(1.4, 6.2)
  );
  vec2 secondWarp = vec2(
    secondField,
    noise(point * 1.25 + firstWarp * (1.1 * u_warp) + vec2(8.3, 2.1))
  );

  float pooledPigment = fbm(
    point * 1.18 + secondWarp * (1.7 * u_warp) + drift * 0.35
  );
  float broadWash = firstWarp.y;

  // One continuously warped lower boundary creates the broad painted wash.
  float boundary = 0.48;
  boundary += (secondWarp.x - 0.5) * 0.29;
  boundary += (broadWash - 0.5) * 0.17;
  boundary += sin(uv.x * 3.2 + motionTime * 0.72) * 0.035;

  float feather = u_edgeSoftness * mix(0.78, 1.25, broadWash);
  float wash = smoothstep(boundary - feather, boundary + feather, uv.y);

  float granulation = noise(
    point * 5.2 + secondWarp * 0.85 + drift * 1.3
  );
  float density = 0.98;
  density += (pooledPigment - 0.5) * 0.42;
  density += (broadWash - 0.5) * 0.28;
  density += (granulation - 0.5) * u_grain * 1.6;
  density *= mix(0.70, 1.08, smoothstep(0.25, 0.75, pooledPigment));

  float edgeDistance = (uv.y - boundary) / max(feather, 0.001);
  float wetEdge = exp(-edgeDistance * edgeDistance * 2.2) * 0.10;
  float opacity = clamp(
    (wash * density + wetEdge * wash) * u_intensity,
    0.0,
    1.0
  );

  float lowerPigment = smoothstep(boundary - 0.10, boundary + 0.24, uv.y);
  float upperPigment = smoothstep(0.67, 1.0, uv.y);
  vec3 pigment = mix(u_mist, u_secondary, lowerPigment);
  pigment = mix(pigment, u_primary, upperPigment * 0.86);
  pigment = mix(
    pigment,
    u_secondary,
    clamp((secondWarp.y - 0.55) * 0.24, 0.0, 0.12)
  );

  vec3 color = mix(u_surface, pigment, opacity);
  gl_FragColor = vec4(color, 1.0);
}

attribute float aDuration;
attribute float aGlyphIndex;
attribute float aLift;
attribute float aPhase;
attribute float aSize;
attribute float aTone;

uniform float uDevicePixelRatio;
uniform vec3 uFadeColor;
uniform float uGlyphCount;
uniform float uGlyphSize;
uniform vec3 uPalette[3];
uniform float uReducedMotion;
uniform float uSphereRadius;
uniform float uTime;
uniform vec2 uViewportSize;

varying float vAlpha;
varying float vGlyphIndex;
varying vec3 vColor;

void main() {
  float time = mix(uTime / max(aDuration, 1.0), 0.0, uReducedMotion);
  float progress = fract(aPhase + time);
  float rotation = mix(
    -0.022,
    0.205,
    progress
  );
  float shellRadius = uSphereRadius + aLift;
  float perspectiveSpread = mix(1.0, 1.028, progress);
  float horizontal = position.x * uViewportSize.x * perspectiveSpread;
  float ringRadius = sqrt(
    max(shellRadius * shellRadius - horizontal * horizontal, 1.0)
  );
  vec3 shellPosition = vec3(
    horizontal,
    ringRadius * cos(rotation),
    ringRadius * sin(rotation)
  );

  float emerge = smoothstep(0.035, 0.16, progress);
  float fade = 1.0 - smoothstep(0.62, 0.96, progress);
  float limbEnergy = mix(0.84, 1.0, smoothstep(0.08, 0.24, progress));
  float liveAlpha = emerge * fade * limbEnergy;
  float stillAlpha = 0.48 + 0.36 * sin(aPhase * 6.28318530718);
  vAlpha = mix(liveAlpha, max(stillAlpha, 0.22), uReducedMotion);

  float proximityScale = mix(0.74, 1.56, progress);
  gl_PointSize = clamp(
    uGlyphSize * aSize * proximityScale * max(uDevicePixelRatio, 1.0),
    1.0,
    48.0
  );
  gl_Position = projectionMatrix * modelViewMatrix * vec4(shellPosition, 1.0);

  int tone = int(aTone + 0.5);
  vec3 toneColor = uPalette[0];
  if (tone == 1) toneColor = uPalette[1];
  else if (tone == 2) toneColor = uPalette[2];

  vec3 crestColor = mix(uPalette[2], toneColor, 0.18);
  vec3 emberColor = mix(
    uPalette[1],
    uFadeColor,
    smoothstep(0.34, 0.94, progress)
  );
  vColor = mix(crestColor, emberColor, smoothstep(0.12, 0.88, progress));

  vGlyphIndex = mod(aGlyphIndex + floor(aPhase + time), uGlyphCount);
}

uniform sampler2D uAtlas;
uniform float uGlyphCount;

varying float vAlpha;
varying float vGlyphIndex;
varying vec3 vColor;

void main() {
  vec2 atlasUv = vec2(
    (vGlyphIndex + gl_PointCoord.x) / uGlyphCount,
    1.0 - gl_PointCoord.y
  );
  float ink = texture2D(uAtlas, atlasUv).a;
  float alpha = ink * vAlpha;

  if (alpha <= 0.025) discard;

  gl_FragColor = vec4(vColor, alpha);
}

varying vec3 vLocalPosition;

void main() {
  vLocalPosition = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

uniform vec3 uAccentColor;
uniform vec3 uGlowBaseColor;
uniform float uIntensity;
uniform float uOpacity;
uniform float uShadowMix;
uniform float uPatternBias;
uniform float uTravel;

varying vec3 vLocalPosition;

const float PI = 3.14159265359;
const float TAU = 6.28318530718;

void main() {
  float angle = atan(vLocalPosition.z, vLocalPosition.x);
  float orbit = fract((angle + PI) / TAU);
  float travel = fract(uTravel + sin((orbit + uTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.34, wrappedDistance);
  float pulseBand = 0.5 + 0.5 * sin((orbit * 7.0 - travel * 4.5) * TAU);
  float ember = 0.64 + hotCore * 0.42 + pulseBand * 0.34;
  float verticalLift = 0.84 + 0.16 * clamp(vLocalPosition.y + 0.5, 0.0, 1.0);
  float glow = 0.12 + sweep * 0.72 + hotCore * 0.32;
  float alpha = uOpacity * glow * ember * verticalLift;
  vec3 accentColor =
    uAccentColor * (0.82 + sweep * 0.62 + hotCore * 0.68) * uIntensity;
  vec3 color = mix(
    accentColor,
    mix(uGlowBaseColor, accentColor, hotCore),
    uShadowMix
  );

  gl_FragColor = vec4(clamp(color, 0.0, 1.0), alpha);
}

uniform vec3 uAccentColor;
uniform vec3 uGlowBaseColor;
uniform float uFacePhaseBias;
uniform float uFaceRimWidth;
uniform float uFaceVariant;
uniform float uOpacity;
uniform float uShadowMix;
uniform float uPatternBias;
uniform float uTravel;

varying vec3 vLocalPosition;

const float PI = 3.14159265359;
const float TAU = 6.28318530718;

void main() {
  float faceThreshold = 0.495;
  bool onXAxisFace = abs(vLocalPosition.x) >= faceThreshold;
  bool onYAxisFace = abs(vLocalPosition.y) >= faceThreshold;
  bool onZAxisFace = abs(vLocalPosition.z) >= faceThreshold;

  float xFaceRim = 1.0 - smoothstep(
    0.0,
    uFaceRimWidth,
    min(0.5 - abs(vLocalPosition.y), 0.5 - abs(vLocalPosition.z))
  );
  float yFaceRim = 1.0 - smoothstep(
    0.0,
    uFaceRimWidth,
    min(0.5 - abs(vLocalPosition.x), 0.5 - abs(vLocalPosition.z))
  );
  float zFaceRim = 1.0 - smoothstep(
    0.0,
    uFaceRimWidth,
    min(0.5 - abs(vLocalPosition.x), 0.5 - abs(vLocalPosition.y))
  );
  float faceBleed =
    (onXAxisFace ? xFaceRim : 0.0) +
    (onYAxisFace ? yFaceRim : 0.0) +
    (onZAxisFace ? zFaceRim : 0.0);
  faceBleed = min(faceBleed, 1.0);

  float angle = atan(vLocalPosition.z, vLocalPosition.x);
  float orbit = fract((angle + PI) / TAU);
  float faceTravel = fract(uTravel + uFacePhaseBias * uFaceVariant);
  float travel = fract(faceTravel + sin((orbit + faceTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.34, wrappedDistance);
  float pulseBand =
    0.5 +
    0.5 *
      sin(
        (
          orbit * 7.0 -
          travel * 4.5 +
          uFacePhaseBias * 1.7 * uFaceVariant
        ) *
          TAU
      );
  float ember = 0.62 + hotCore * 0.34 + pulseBand * 0.28;
  float verticalLift = 0.84 + 0.16 * clamp(vLocalPosition.y + 0.5, 0.0, 1.0);
  float alpha =
    uOpacity *
    faceBleed *
    (sweep * 0.74 + hotCore * 0.26) *
    ember *
    verticalLift;
  vec3 baseAccentColor =
    uAccentColor * (0.34 + sweep * 0.28 + hotCore * 0.34);
  vec3 radiantAccent = mix(
    uAccentColor,
    vec3(1.0, 0.78, 0.52),
    hotCore * 0.58
  );
  vec3 boostedAccentColor =
    radiantAccent * (0.48 + sweep * 0.56 + hotCore * 0.78);
  vec3 accentColor = mix(
    baseAccentColor,
    boostedAccentColor,
    uFaceVariant
  );
  vec3 color = mix(
    accentColor,
    mix(uGlowBaseColor, accentColor, hotCore),
    uShadowMix
  );

  gl_FragColor = vec4(clamp(color, 0.0, 1.0), alpha);
}

varying vec2 vRailUv;

void main() {
  vRailUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

uniform vec3 uAccentColor;
uniform float uOpacity;
uniform float uPatternBias;
uniform float uTravel;

varying vec2 vRailUv;

const float TAU = 6.28318530718;

void main() {
  float orbit = fract(vRailUv.y);
  float travel = fract(uTravel + sin((orbit + uTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.26, wrappedDistance);
  float laserCore = 1.0 - smoothstep(0.0, 0.12, wrappedDistance);
  float pulseBand = 0.5 + 0.5 * sin((orbit * 7.0 - travel * 4.5) * TAU);
  float edgeGlint =
    smoothstep(
      0.58,
      1.0,
      0.5 + 0.5 * sin((orbit * 11.0 - travel * 8.5) * TAU)
    ) *
    (0.24 + sweep * 0.76);
  float flare = laserCore * (0.72 + pulseBand * 0.52);
  float ember =
    0.62 + hotCore * 0.34 + pulseBand * 0.26 + flare * 0.42 + edgeGlint * 0.18;
  float cylindricalLift = 0.94 + 0.06 * sin(vRailUv.x * TAU);
  float glow =
    0.1 + sweep * 0.58 + hotCore * 0.42 + flare * 0.66 + edgeGlint * 0.24;
  float intensity = clamp(
    uOpacity * glow * ember * cylindricalLift,
    0.0,
    1.0
  );
  vec3 color =
    uAccentColor *
    (0.78 + sweep * 0.48 + hotCore * 0.54 + flare * 0.88 + edgeGlint * 0.28);
  vec3 moltenBase = uAccentColor * 0.74;
  vec3 lightModeColor = mix(moltenBase, color, intensity);
  float railEdgeSoftness =
    smoothstep(0.0, 0.12, vRailUv.x) *
    smoothstep(0.0, 0.12, 1.0 - vRailUv.x);
  vec3 antialiasedColor = mix(moltenBase, lightModeColor, railEdgeSoftness);

  gl_FragColor = vec4(antialiasedColor, 1.0);
}

uniform vec3 uAccentColor;
uniform float uOpacity;
uniform float uPatternBias;
uniform float uTravel;

varying vec2 vRailUv;

const float TAU = 6.28318530718;

void main() {
  float orbit = fract(vRailUv.y);
  float travel = fract(uTravel + sin((orbit + uTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.28, wrappedDistance);
  float laserCore = 1.0 - smoothstep(0.0, 0.14, wrappedDistance);
  float pulseBand = 0.5 + 0.5 * sin((orbit * 7.0 - travel * 4.5) * TAU);
  float edgeGlint =
    smoothstep(
      0.6,
      1.0,
      0.5 + 0.5 * sin((orbit * 11.0 - travel * 8.5) * TAU)
    ) *
    (0.18 + sweep * 0.82);
  float flare = laserCore * (0.7 + pulseBand * 0.46);
  float ember =
    0.58 + hotCore * 0.28 + pulseBand * 0.22 + flare * 0.34 + edgeGlint * 0.14;
  float cylindricalLift = 0.9 + 0.1 * sin(vRailUv.x * TAU);
  float intensity = clamp(
    uOpacity *
      (sweep * 0.34 + hotCore * 0.28 + flare * 0.42 + edgeGlint * 0.18) *
      ember *
      cylindricalLift,
    0.0,
    1.0
  );
  vec3 color =
    uAccentColor *
    (0.34 + sweep * 0.28 + hotCore * 0.38 + flare * 0.6 + edgeGlint * 0.24);
  vec3 moltenBase = uAccentColor * 0.34;
  vec3 lightModeColor = mix(moltenBase, color, intensity);
  float railEdgeSoftness =
    smoothstep(0.0, 0.18, vRailUv.x) *
    smoothstep(0.0, 0.18, 1.0 - vRailUv.x);
  vec3 antialiasedColor = mix(moltenBase, lightModeColor, railEdgeSoftness);

  gl_FragColor = vec4(antialiasedColor, 1.0);
}

attribute vec2 a_position;
void main() {
  gl_Position = vec4(a_position, 0.0, 1.0);
}

precision highp float;

uniform vec2 u_resolution;
uniform vec2 u_size;
uniform vec4 u_points[

];
uniform vec3 u_light;
uniform float u_time;

const vec3 cyan = vec3(54.0, 204.0, 255.0) / 255.0;
const vec3 lilac = vec3(168.0, 153.0, 255.0) / 255.0;
const vec3 pink = vec3(244.0, 180.0, 229.0) / 255.0;
const float spread = 6.8;
const float tunnelDepth = 0.8;

float gaussian(float x, float width) {
  return exp(-x * x / (width * width));
}

vec3 spectrum(float phase) {
  float cycle = 0.5 + 0.5 * sin(phase);
  return cycle < 0.5
    ? mix(cyan, lilac, cycle * 2.0)
    : mix(lilac, pink, cycle * 2.0 - 1.0);
}

// Refract the existing contour beams through a smooth tunnel around their
// shared source. Pixels and their contour anchors must use this same mapping.
vec2 tunnel(vec2 p) {
  vec2 delta = p - u_light.xy;
  float radius = length(delta);
  float aperture = 0.7;
  float travel = max(radius - aperture, 0.0);
  float reach = max(spread * 0.55, 1.0);
  float normalized = travel / reach;
  float progress = normalized * normalized / (1.0 + normalized * normalized);
  float angle = -0.05 * progress;
  float c = cos(angle);
  float s = sin(angle);
  vec2 rotated = vec2(c * delta.x + s * delta.y, -s * delta.x + c * delta.y);
  // Logarithmic perspective is monotonic at every setting: no folding,
  // repeated bends, or discontinuities as the source crosses a letter.
  float compressed = reach * log(1.0 + travel * tunnelDepth / reach) / tunnelDepth;
  float mappedRadius = min(radius, aperture) + compressed;
  return u_light.xy + rotated * mappedRadius / max(radius, 0.0001);
}

void main() {
  vec2 p = (gl_FragCoord.xy / u_resolution - 0.5) * u_size;
  vec2 fieldP = tunnel(p);
  float t = u_time;
  vec3 radiance = vec3(0.0);
  float density = 0.0;
  const float amplification = 3.5;

  // All rays share one moving light behind the text. Each contour point
  // projects away from that light, so cursor movement steers the whole field.
  for (int i = 0; i <

; i++) {
    vec4 point = u_points[i];
    if (point.z < 0.003) continue;
    // Map the fixed ink contour into the same space as the sampled pixel.
    // At p == point.xy, delta stays zero even after the light has moved away.
    // Leaving the anchor unwarped makes the visible root slide off its letter.
    vec2 origin = tunnel(point.xy);
    vec2 fromLight = origin - u_light.xy;
    float separation = length(fromLight);
    vec2 direction = fromLight / max(separation, 0.001);
    vec2 delta = fieldP - origin;
    float along = dot(delta, direction);
    float across = delta.x * direction.y - delta.y * direction.x;
    float distance = max(along, 0.0);
    float phase = point.w;

    // A single shallow bend near the outside; no waves along a ribbon.
    vec2 edgeReach = (u_size * 0.5 - sign(direction) * point.xy)
      / max(abs(direction), vec2(0.001));
    float reach = min(edgeReach.x, edgeReach.y);
    float onset = reach * (0.42 + 0.06 * sin(phase));
    float span = max(reach - onset, 0.5);
    float beyond = max(distance - onset, 0.0);
    // Ease through a straight beam when crossing an axis. A sign() here
    // flips the outer bend in a single frame even when the source is smooth.
    float curve = 2.0 * direction.x * direction.y * (0.3 + 0.07 * sin(phase * 1.7));
    curve *= (1.0 + 0.12 * sin(t * 0.27 + phase));
    float bend = curve * beyond * beyond / (2.0 * span);
    float slope = curve * beyond / span;
    across = (across - bend) / sqrt(1.0 + slope * slope);

    float width = (0.055 + distance * (0.15 + 0.03 * sin(phase * 2.1)));
    width *= (1.0 + 0.1 * sin(t * 0.3 + phase));
    float side = sin(phase * 1.3) < 0.0 ? -1.0 : 1.0;
    float sheet = gaussian(across - width * side * 0.4, width);
    float bloom = gaussian(across, width * 2.3 + 0.1);
    float rim = gaussian(across, (0.025 + distance * 0.018));
    float forward = smoothstep(-0.08, 0.22, along);
    float falloff = exp(-distance / (spread * 0.82));
    float flow = distance * 0.55 - t * 0.3 + phase;
    float power = point.z * forward * falloff * (0.9 + 0.1 * sin(flow));
    // A broad fade hides the rapid angular change as the light passes an
    // outline point; there is no hard distance cutoff that can flash a ray.
    power *= smoothstep(0.0, 0.28, separation);

    vec3 color = spectrum(t * 0.22 + phase * 0.4 + distance * 0.27);
    vec3 bodyColor = mix(color, vec3(0.9, 0.97, 1.0), 0.2);
    vec3 rimColor = mix(color, vec3(0.94, 0.99, 1.0), 0.8);
    // Concentrate the extra light inside the ribbons. Boosting the broad
    // haze equally washes out the blue gaps and hides their luminous cores.
    float body = (sheet * 0.32 * amplification + bloom * 0.09 * 1.35) * power;
    float core = gaussian(across - width * side * 0.4, width * 0.42);
    core *= 0.65 * power;
    float edge = rim * 0.17 * power * 2.2;
    float contact = exp(-dot(delta, delta) / 0.025) * point.z * 0.1 * amplification;
    radiance += bodyColor * body + rimColor * (edge + contact) + vec3(0.97, 0.99, 1.0) * core;
    density += body + edge + contact + core;
  }

  // A diffuse backlight also shows through counters such as O and U.
  // The visible letter sits in front of this continuous field.
  vec2 lightDelta = fieldP - u_light.xy;
  float glow = exp(-dot(lightDelta, lightDelta) / 0.65) * u_light.z * 0.48 * 2.2;
  float haze = exp(-dot(lightDelta, lightDelta) / 4.0) * u_light.z * 0.12;
  vec3 sourceColor = mix(cyan, spectrum(t * 0.22), 0.35);
  radiance += mix(sourceColor, vec3(0.93, 0.98, 1.0), 0.7) * glow + sourceColor * haze;
  density += glow + haze;

  vec3 color = radiance / max(density, 0.001);
  float alpha = (1.0 - exp(-density * 1.35));
  gl_FragColor = vec4(color * alpha, alpha);
}

#version 300 es
out vec2 uv;
void main() {
  vec2 corner = vec2((gl_VertexID << 1) & 2, gl_VertexID & 2);
  uv = corner;
  gl_Position = vec4(corner * 2.0 - 1.0, 0.0, 1.0);
}

#version 300 es
precision highp float;
precision highp sampler2D;
in vec2 uv;
out vec4 color;
uniform vec2 grid;
uniform vec2 box;
uniform vec2 cover;
uniform float dt;

float wash(vec2 p, vec2 center, vec2 spread, float tilt) {
  vec2 v = p - center;
  v.x -= tilt * v.y;
  v /= spread;
  return exp(-dot(v, v));
}

vec3 printAt(vec2 image) {
  // The 16:9 print folds around a horizontal axis: blue lobes on the left and a small violet caustic on the right.
  float dy = image.y - 0.442;
  vec2 p = vec2(image.x, sqrt(dy * dy + 0.00032));
  vec3 ink = vec3(248, 233, 254);
  ink += vec3(-34, -4, 0) * wash(p, vec2(0.450, 0.262), vec2(0.128, 0.089), 0.193);
  ink += vec3(-39, -4, 1) * wash(p, vec2(0.295, 0.149), vec2(0.163, 0.147), 0.835);
  ink += vec3(-22, 5, 0) * wash(p, vec2(0.377, 0.022), vec2(0.147, 0.193), 0.967);
  ink += vec3(18, -3, -5) * wash(p, vec2(0.097, 0.100), vec2(0.065, 0.240), 0.871);
  ink += vec3(-13, 27, 2) * wash(p, vec2(-0.337, -0.138), vec2(0.104, 0.633), 0.898);
  ink += vec3(15, -27, -18) * wash(p, vec2(-0.039, 0.221), vec2(0.046, 0.212), 0.569);
  ink += vec3(14, -26, -37) * wash(p, vec2(0.864, -0.048), vec2(0.153, 0.144), 0.107);
  ink += vec3(-67, -13, 23) * wash(p, vec2(0.874, 0.037), vec2(0.040, 0.075), 0.004);
  ink += vec3(-9, 17, 0) * wash(p, vec2(1.066, 0.564), vec2(0.314, 0.285), 1.349);
  return ink / 255.0;
}

vec3 original(vec2 q) {
  return printAt(q * cover + vec2(0.0, (1.0 - cover.y) * 0.5));
}

float pigmentStrength(vec3 stock) {
  float blueInk = smoothstep(0.085, 0.218, stock.b - stock.r);
  float roseInk = smoothstep(0.054, 0.113, stock.r - stock.g);
  return max(blueInk, roseInk);
}

// Pale stirred inks keep the article type legible as a stroke crosses the title.
const vec3 firstInk = vec3(0.985, 0.845, 0.930);
const vec3 secondInk = vec3(0.639, 0.847, 0.994);

uniform float reversePrint;

vec3 original(vec2 q) {
  q.x = mix(q.x, 1.0 - q.x, reversePrint);
  // Mint pools near the top of the print, with narrow diagonal streaks running into emerald.
  vec2 p = q * cover + (1.0 - cover) * 0.5;
  vec3 ink = vec3(23, 170, 107) + vec3(-13, 12, 30) * (1.0 - p.y);
  ink += vec3(88, 24, -43) * wash(p, vec2(-0.063, 0.102), vec2(0.105, 0.496), -0.257);
  ink += vec3(217, 67, 106) * wash(p, vec2(0.320, -0.019), vec2(0.205, 0.330), -0.351);
  ink += vec3(44, -10, 2) * wash(p, vec2(0.598, 0.051), vec2(0.159, 0.620), -0.461);
  ink += vec3(66, 34, 58) * wash(p, vec2(0.716, 0.289), vec2(0.056, 0.760), -0.176);
  ink += vec3(-78, -27, -38) * wash(p, vec2(0.238, 0.205), vec2(0.067, 0.235), -0.471);
  ink += vec3(55, 0, -18) * wash(p, vec2(0.074, 0.475), vec2(0.084, 0.151), -0.384);
  ink += vec3(-11, -35, -15) * wash(p, vec2(0.670, 0.735), vec2(0.290, 0.554), -0.153);
  ink += vec3(98, 39, 51) * wash(p, vec2(0.841, 0.035), vec2(0.111, 0.200), -0.116);
  ink += vec3(-18, -13, -29) * wash(p, vec2(0.764, -0.016), vec2(0.040, 0.425), -0.164);
  // Pool darker jade between the masthead and the papers, leaving the diagonal caustics visible.
  float jade = wash(q, vec2(0.14, 0.20), vec2(0.22, 0.12), -0.32);
  ink = mix(ink, vec3(8, 151, 105), 0.64 * jade);

  // The reading area begins below the artwork on compact covers and alongside it on wide covers.
  float belowArt = smoothstep(0.25, 0.39, q.y);
  float leading = 1.0 - smoothstep(0.40, 0.69, q.x);
  float writingArea = belowArt * mix(1.0, leading, smoothstep(656.0, 752.0, box.x));
  float masthead = 1.0 - smoothstep(38.0, 77.0, q.y * box.y);
  return mix(ink / 255.0, vec3(0.87, 0.97, 0.86), max(0.82 * writingArea, 0.58 * masthead));
}

float pigmentStrength(vec3 stock) {
  // Replenish the pale writing stock as well as the jade when the fluid drifts.
  return max(smoothstep(0.10, 0.52, stock.g - stock.r), smoothstep(0.68, 0.88, stock.r));
}

const vec3 firstInk = vec3(0.86, 0.96, 0.84);
const vec3 secondInk = vec3(0.52, 0.84, 0.70);

uniform float forcingTime;
vec2 turn(vec2 v) { return vec2(-v.y, v.x); }
vec2 gyre(vec2 q, vec2 origin, float width) {
  vec2 d = (q - origin) * grid / min(grid.x, grid.y);
  return turn(d) * exp(-dot(d, d) / (width * width));
}
vec2 resting(vec2 q) {
  float t = forcingTime;
  // Slowly wandering convection keeps transporting pigments after the initial field has mixed.
  vec2 inlet = vec2(0.33, 0.43) + vec2(0.15 * sin(0.34*t), 0.14 * sin(0.27*t));
  vec2 outlet = vec2(0.75, 0.58) + vec2(0.14 * sin(0.30*t), -0.16 * sin(0.37*t));
  return min(grid.x, grid.y) * (
    (1.25 + 0.38 * sin(0.48*t)) * gyre(q, inlet, 0.48) -
    (1.12 - 0.40 * sin(0.39*t)) * gyre(q, outlet, 0.40) +
    0.52 * gyre(q, vec2(0.16, 0.85 + 0.10 * sin(0.29*t)), 0.31));
}

uniform vec4 stroke;
uniform vec4 brush;
vec2 fromStroke(vec2 q) {
  vec2 segment = stroke.zw - stroke.xy;
  float along = clamp(dot(q * box - stroke.xy, segment) / max(dot(segment, segment), 0.01), 0.0, 1.0);
  return (q * box - mix(stroke.xy, stroke.zw, along)) / max(brush.z, 1.0);
}

uniform sampler2D velocity;
void main() {
  vec2 here = texture(velocity, uv).xy;
  vec2 midpoint = uv - 0.5 * dt * here / grid;
  vec2 back = uv - dt * texture(velocity, midpoint).xy / grid;
  vec2 v = texture(velocity, back).xy;
  v = mix(v, resting(uv), 1.0 - exp(-0.33 * dt));

  if (brush.w > 0.001) {
    vec2 r = fromStroke(uv);
    float d = length(r);
    vec2 dir = normalize(brush.xy + vec2(0.001, 0.0));
    vec2 n = r / max(d, 0.001);
    // Potential flow around a translating cylinder sends pigment ahead and around its sides.
    vec2 slip = (2.0 * n * dot(n, dir) - dir) / max(1.0, d * d);
    vec2 desired = mix(dir, slip, smoothstep(0.58, 1.15, d));
    // Opposite shear behind each shoulder rolls up into two unequal vortices.
    vec2 side = turn(dir);
    vec2 a = r + 0.68 * dir - 0.72 * side;
    vec2 b = r + 0.86 * dir + 0.61 * side;
    desired += 1.85 * turn(a) * exp(-3.6 * dot(a, a)) - 1.52 * turn(b) * exp(-3.2 * dot(b, b));
    float grip = (1.0 - smoothstep(1.05, 2.85, d)) * brush.w;
    v = mix(v, desired * length(brush.xy) * grid / box, 1.0 - exp(-9.0 * dt * grip));
  }
  float limit = min(grid.x, grid.y) * 1.75;
  v *= min(1.0, limit / max(length(v), 0.001));
  v *= smoothstep(vec2(0.0), vec2(2.2), min(uv, 1.0 - uv) * grid);
  color = vec4(v, 0.0, 1.0);
}

uniform sampler2D velocity;
void main() {
  vec2 d = 1.0 / grid;
  vec2 l = texture(velocity, uv - vec2(d.x, 0.0)).xy;
  vec2 r = texture(velocity, uv + vec2(d.x, 0.0)).xy;
  vec2 t = texture(velocity, uv - vec2(0.0, d.y)).xy;
  vec2 b = texture(velocity, uv + vec2(0.0, d.y)).xy;
  color = vec4(0.5 * (r.x - l.x + b.y - t.y), 0.5 * (r.y - l.y - b.x + t.x), 0.0, 1.0);
}

uniform sampler2D pressure;
uniform sampler2D derivatives;
void main() {
  vec2 d = 1.0 / grid;
  float neighbors = texture(pressure, uv - vec2(d.x, 0.0)).r + texture(pressure, uv + vec2(d.x, 0.0)).r
    + texture(pressure, uv - vec2(0.0, d.y)).r + texture(pressure, uv + vec2(0.0, d.y)).r;
  color = vec4((neighbors - texture(derivatives, uv).r) * 0.25, 0.0, 0.0, 1.0);
}

uniform sampler2D velocity;
uniform sampler2D pressure;
uniform sampler2D derivatives;
void main() {
  vec2 d = 1.0 / grid;
  vec2 x = vec2(d.x, 0.0), y = vec2(0.0, d.y);
  vec2 gradient = 0.5 * vec2(texture(pressure, uv+x).r - texture(pressure, uv-x).r,
    texture(pressure, uv+y).r - texture(pressure, uv-y).r);
  vec2 curlGradient = vec2(abs(texture(derivatives, uv+x).g) - abs(texture(derivatives, uv-x).g),
    abs(texture(derivatives, uv+y).g) - abs(texture(derivatives, uv-y).g));
  vec2 n = curlGradient / max(length(curlGradient), 0.01);
  float curl = texture(derivatives, uv).g;
  vec2 v = texture(velocity, uv).xy - gradient + dt * 1.5 * curl * vec2(n.y, -n.x);
  color = vec4(v, 0.0, 1.0);
}

uniform sampler2D previousPigment;
uniform sampler2D currentPigment;
uniform float frameBlend;
uniform vec4 lens;
void main() {
  vec2 p = vec2(uv.x, 1.0 - uv.y) * box;
  vec2 fromLens = p - lens.xy;
  if (length(fromLens) < lens.z) p = lens.xy + fromLens / lens.w;
  vec2 q = p / box;
  color = vec4(mix(texture(previousPigment, q).rgb, texture(currentPigment, q).rgb, frameBlend), 1.0);
}

uniform int pigment;
void main() {
  color = pigment == 1 ? vec4(original(uv), 0.0) : vec4(resting(uv), 0.0, 1.0);
}

uniform sampler2D velocity;
uniform sampler2D previousPigment;
void main() {
  vec2 v = texture(velocity, uv).xy;
  vec2 midpoint = uv - 0.5 * dt * v / grid;
  vec2 from = uv - dt * texture(velocity, midpoint).xy / grid;
  vec4 carried = texture(previousPigment, from);
  // The alpha channel carries mixing history. Disturbed ink exchanges more slowly with the stock.
  float mixed = carried.a * exp(-0.48 * dt);
  vec3 stock = original(uv);
  float reservoir = pigmentStrength(stock);
  float exchange = mix(mix(0.53, 2.35, reservoir), 0.16, mixed);
  vec3 pigment = mix(carried.rgb, stock, 1.0 - exp(-exchange * dt));
  if (brush.w > 0.001) {
    vec2 r = fromStroke(uv);
    vec2 dir = normalize(brush.xy + vec2(0.001, 0.0));
    float side = dot(r, vec2(-dir.y, dir.x));
    float front = dot(r, dir);
    vec2 shoulder = vec2((front - 0.22) / 0.90, (abs(side) - 0.71) / 0.34);
    float contact = exp(-dot(shoulder, shoulder)) * brush.w;
    vec3 entrained = mix(firstInk, secondInk, smoothstep(-0.35, 0.35, side));
    pigment = mix(pigment, entrained, 1.0 - exp(-2.7 * dt * contact));
    mixed = mix(mixed, 1.0, 1.0 - exp(-6.0 * dt * contact));
  }
  color = vec4(pigment, mixed);
}

attribute vec2 a_position;
varying vec2 v_uv;

void main() {
  v_uv = a_position * 0.5 + 0.5;
  gl_Position = vec4(a_position, 0.0, 1.0);
}

uniform float u_edgeSoftness;
uniform float u_grain;
uniform float u_intensity;
uniform vec3 u_mist;
uniform vec3 u_primary;
uniform vec2 u_resolution;
uniform vec3 u_secondary;
uniform float u_speed;
uniform vec3 u_surface;
uniform float u_time;
uniform float u_warp;

varying vec2 v_uv;

float random(vec2 point) {
  vec3 point3 = fract(vec3(point.xyx) * 0.1031);
  point3 += dot(point3, point3.yzx + 33.33);
  return fract((point3.x + point3.y) * point3.z);
}

float noise(vec2 point) {
  vec2 cell = floor(point);
  vec2 local = fract(point);
  vec2 curve = local * local * (3.0 - 2.0 * local);

  float bottomLeft = random(cell);
  float bottomRight = random(cell + vec2(1.0, 0.0));
  float topLeft = random(cell + vec2(0.0, 1.0));
  float topRight = random(cell + vec2(1.0, 1.0));

  return mix(
    mix(bottomLeft, bottomRight, curve.x),
    mix(topLeft, topRight, curve.x),
    curve.y
  );
}

float fbm(vec2 point) {
  float value = 0.0;
  float amplitude = 0.52;
  mat2 rotation = mat2(0.80, -0.60, 0.60, 0.80);

  for (int octave = 0; octave < FBM_OCTAVES; octave++) {
    value += amplitude * noise(point);
    point = rotation * point * 2.03 + vec2(7.1, 3.7);
    amplitude *= 0.5;
  }

  return value;
}

void main() {
  vec2 uv = v_uv;
  float aspect = min(u_resolution.x / max(u_resolution.y, 1.0), 3.0);
  float motionTime = u_time * max(u_speed, 0.0);

  vec2 point = vec2(uv.x * (1.12 + aspect * 0.16), uv.y * 1.08);
  vec2 drift = vec2(
    motionTime * 0.34 + sin(motionTime * 0.41) * 0.12,
    -motionTime * 0.07 + cos(motionTime * 0.29) * 0.10
  );

  vec2 firstWarp = vec2(
    fbm(point * 1.05 + drift),
    fbm(point * 1.05 + drift + vec2(4.8, 1.7))
  );
  float secondField = fbm(
    point * 1.45 + firstWarp * (1.25 * u_warp) + vec2(1.4, 6.2)
  );
  vec2 secondWarp = vec2(
    secondField,
    noise(point * 1.25 + firstWarp * (1.1 * u_warp) + vec2(8.3, 2.1))
  );

  float pooledPigment = fbm(
    point * 1.18 + secondWarp * (1.7 * u_warp) + drift * 0.35
  );
  float broadWash = firstWarp.y;

  // One continuously warped lower boundary creates the broad painted wash.
  float boundary = 0.48;
  boundary += (secondWarp.x - 0.5) * 0.29;
  boundary += (broadWash - 0.5) * 0.17;
  boundary += sin(uv.x * 3.2 + motionTime * 0.72) * 0.035;

  float feather = u_edgeSoftness * mix(0.78, 1.25, broadWash);
  float wash = smoothstep(boundary - feather, boundary + feather, uv.y);

  float granulation = noise(
    point * 5.2 + secondWarp * 0.85 + drift * 1.3
  );
  float density = 0.98;
  density += (pooledPigment - 0.5) * 0.42;
  density += (broadWash - 0.5) * 0.28;
  density += (granulation - 0.5) * u_grain * 1.6;
  density *= mix(0.70, 1.08, smoothstep(0.25, 0.75, pooledPigment));

  float edgeDistance = (uv.y - boundary) / max(feather, 0.001);
  float wetEdge = exp(-edgeDistance * edgeDistance * 2.2) * 0.10;
  float opacity = clamp(
    (wash * density + wetEdge * wash) * u_intensity,
    0.0,
    1.0
  );

  float lowerPigment = smoothstep(boundary - 0.10, boundary + 0.24, uv.y);
  float upperPigment = smoothstep(0.67, 1.0, uv.y);
  vec3 pigment = mix(u_mist, u_secondary, lowerPigment);
  pigment = mix(pigment, u_primary, upperPigment * 0.86);
  pigment = mix(
    pigment,
    u_secondary,
    clamp((secondWarp.y - 0.55) * 0.24, 0.0, 0.12)
  );

  vec3 color = mix(u_surface, pigment, opacity);
  gl_FragColor = vec4(color, 1.0);
}

attribute float aDuration;
attribute float aGlyphIndex;
attribute float aLift;
attribute float aPhase;
attribute float aSize;
attribute float aTone;

uniform float uDevicePixelRatio;
uniform vec3 uFadeColor;
uniform float uGlyphCount;
uniform float uGlyphSize;
uniform vec3 uPalette[3];
uniform float uReducedMotion;
uniform float uSphereRadius;
uniform float uTime;
uniform vec2 uViewportSize;

varying float vAlpha;
varying float vGlyphIndex;
varying vec3 vColor;

void main() {
  float time = mix(uTime / max(aDuration, 1.0), 0.0, uReducedMotion);
  float progress = fract(aPhase + time);
  float rotation = mix(
    -0.022,
    0.205,
    progress
  );
  float shellRadius = uSphereRadius + aLift;
  float perspectiveSpread = mix(1.0, 1.028, progress);
  float horizontal = position.x * uViewportSize.x * perspectiveSpread;
  float ringRadius = sqrt(
    max(shellRadius * shellRadius - horizontal * horizontal, 1.0)
  );
  vec3 shellPosition = vec3(
    horizontal,
    ringRadius * cos(rotation),
    ringRadius * sin(rotation)
  );

  float emerge = smoothstep(0.035, 0.16, progress);
  float fade = 1.0 - smoothstep(0.62, 0.96, progress);
  float limbEnergy = mix(0.84, 1.0, smoothstep(0.08, 0.24, progress));
  float liveAlpha = emerge * fade * limbEnergy;
  float stillAlpha = 0.48 + 0.36 * sin(aPhase * 6.28318530718);
  vAlpha = mix(liveAlpha, max(stillAlpha, 0.22), uReducedMotion);

  float proximityScale = mix(0.74, 1.56, progress);
  gl_PointSize = clamp(
    uGlyphSize * aSize * proximityScale * max(uDevicePixelRatio, 1.0),
    1.0,
    48.0
  );
  gl_Position = projectionMatrix * modelViewMatrix * vec4(shellPosition, 1.0);

  int tone = int(aTone + 0.5);
  vec3 toneColor = uPalette[0];
  if (tone == 1) toneColor = uPalette[1];
  else if (tone == 2) toneColor = uPalette[2];

  vec3 crestColor = mix(uPalette[2], toneColor, 0.18);
  vec3 emberColor = mix(
    uPalette[1],
    uFadeColor,
    smoothstep(0.34, 0.94, progress)
  );
  vColor = mix(crestColor, emberColor, smoothstep(0.12, 0.88, progress));

  vGlyphIndex = mod(aGlyphIndex + floor(aPhase + time), uGlyphCount);
}

uniform sampler2D uAtlas;
uniform float uGlyphCount;

varying float vAlpha;
varying float vGlyphIndex;
varying vec3 vColor;

void main() {
  vec2 atlasUv = vec2(
    (vGlyphIndex + gl_PointCoord.x) / uGlyphCount,
    1.0 - gl_PointCoord.y
  );
  float ink = texture2D(uAtlas, atlasUv).a;
  float alpha = ink * vAlpha;

  if (alpha <= 0.025) discard;

  gl_FragColor = vec4(vColor, alpha);
}

varying vec3 vLocalPosition;

void main() {
  vLocalPosition = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

uniform vec3 uAccentColor;
uniform vec3 uGlowBaseColor;
uniform float uIntensity;
uniform float uOpacity;
uniform float uShadowMix;
uniform float uPatternBias;
uniform float uTravel;

varying vec3 vLocalPosition;

const float PI = 3.14159265359;
const float TAU = 6.28318530718;

void main() {
  float angle = atan(vLocalPosition.z, vLocalPosition.x);
  float orbit = fract((angle + PI) / TAU);
  float travel = fract(uTravel + sin((orbit + uTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.34, wrappedDistance);
  float pulseBand = 0.5 + 0.5 * sin((orbit * 7.0 - travel * 4.5) * TAU);
  float ember = 0.64 + hotCore * 0.42 + pulseBand * 0.34;
  float verticalLift = 0.84 + 0.16 * clamp(vLocalPosition.y + 0.5, 0.0, 1.0);
  float glow = 0.12 + sweep * 0.72 + hotCore * 0.32;
  float alpha = uOpacity * glow * ember * verticalLift;
  vec3 accentColor =
    uAccentColor * (0.82 + sweep * 0.62 + hotCore * 0.68) * uIntensity;
  vec3 color = mix(
    accentColor,
    mix(uGlowBaseColor, accentColor, hotCore),
    uShadowMix
  );

  gl_FragColor = vec4(clamp(color, 0.0, 1.0), alpha);
}

uniform vec3 uAccentColor;
uniform vec3 uGlowBaseColor;
uniform float uFacePhaseBias;
uniform float uFaceRimWidth;
uniform float uFaceVariant;
uniform float uOpacity;
uniform float uShadowMix;
uniform float uPatternBias;
uniform float uTravel;

varying vec3 vLocalPosition;

const float PI = 3.14159265359;
const float TAU = 6.28318530718;

void main() {
  float faceThreshold = 0.495;
  bool onXAxisFace = abs(vLocalPosition.x) >= faceThreshold;
  bool onYAxisFace = abs(vLocalPosition.y) >= faceThreshold;
  bool onZAxisFace = abs(vLocalPosition.z) >= faceThreshold;

  float xFaceRim = 1.0 - smoothstep(
    0.0,
    uFaceRimWidth,
    min(0.5 - abs(vLocalPosition.y), 0.5 - abs(vLocalPosition.z))
  );
  float yFaceRim = 1.0 - smoothstep(
    0.0,
    uFaceRimWidth,
    min(0.5 - abs(vLocalPosition.x), 0.5 - abs(vLocalPosition.z))
  );
  float zFaceRim = 1.0 - smoothstep(
    0.0,
    uFaceRimWidth,
    min(0.5 - abs(vLocalPosition.x), 0.5 - abs(vLocalPosition.y))
  );
  float faceBleed =
    (onXAxisFace ? xFaceRim : 0.0) +
    (onYAxisFace ? yFaceRim : 0.0) +
    (onZAxisFace ? zFaceRim : 0.0);
  faceBleed = min(faceBleed, 1.0);

  float angle = atan(vLocalPosition.z, vLocalPosition.x);
  float orbit = fract((angle + PI) / TAU);
  float faceTravel = fract(uTravel + uFacePhaseBias * uFaceVariant);
  float travel = fract(faceTravel + sin((orbit + faceTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.34, wrappedDistance);
  float pulseBand =
    0.5 +
    0.5 *
      sin(
        (
          orbit * 7.0 -
          travel * 4.5 +
          uFacePhaseBias * 1.7 * uFaceVariant
        ) *
          TAU
      );
  float ember = 0.62 + hotCore * 0.34 + pulseBand * 0.28;
  float verticalLift = 0.84 + 0.16 * clamp(vLocalPosition.y + 0.5, 0.0, 1.0);
  float alpha =
    uOpacity *
    faceBleed *
    (sweep * 0.74 + hotCore * 0.26) *
    ember *
    verticalLift;
  vec3 baseAccentColor =
    uAccentColor * (0.34 + sweep * 0.28 + hotCore * 0.34);
  vec3 radiantAccent = mix(
    uAccentColor,
    vec3(1.0, 0.78, 0.52),
    hotCore * 0.58
  );
  vec3 boostedAccentColor =
    radiantAccent * (0.48 + sweep * 0.56 + hotCore * 0.78);
  vec3 accentColor = mix(
    baseAccentColor,
    boostedAccentColor,
    uFaceVariant
  );
  vec3 color = mix(
    accentColor,
    mix(uGlowBaseColor, accentColor, hotCore),
    uShadowMix
  );

  gl_FragColor = vec4(clamp(color, 0.0, 1.0), alpha);
}

varying vec2 vRailUv;

void main() {
  vRailUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

uniform vec3 uAccentColor;
uniform float uOpacity;
uniform float uPatternBias;
uniform float uTravel;

varying vec2 vRailUv;

const float TAU = 6.28318530718;

void main() {
  float orbit = fract(vRailUv.y);
  float travel = fract(uTravel + sin((orbit + uTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.26, wrappedDistance);
  float laserCore = 1.0 - smoothstep(0.0, 0.12, wrappedDistance);
  float pulseBand = 0.5 + 0.5 * sin((orbit * 7.0 - travel * 4.5) * TAU);
  float edgeGlint =
    smoothstep(
      0.58,
      1.0,
      0.5 + 0.5 * sin((orbit * 11.0 - travel * 8.5) * TAU)
    ) *
    (0.24 + sweep * 0.76);
  float flare = laserCore * (0.72 + pulseBand * 0.52);
  float ember =
    0.62 + hotCore * 0.34 + pulseBand * 0.26 + flare * 0.42 + edgeGlint * 0.18;
  float cylindricalLift = 0.94 + 0.06 * sin(vRailUv.x * TAU);
  float glow =
    0.1 + sweep * 0.58 + hotCore * 0.42 + flare * 0.66 + edgeGlint * 0.24;
  float intensity = clamp(
    uOpacity * glow * ember * cylindricalLift,
    0.0,
    1.0
  );
  vec3 color =
    uAccentColor *
    (0.78 + sweep * 0.48 + hotCore * 0.54 + flare * 0.88 + edgeGlint * 0.28);
  vec3 moltenBase = uAccentColor * 0.74;
  vec3 lightModeColor = mix(moltenBase, color, intensity);
  float railEdgeSoftness =
    smoothstep(0.0, 0.12, vRailUv.x) *
    smoothstep(0.0, 0.12, 1.0 - vRailUv.x);
  vec3 antialiasedColor = mix(moltenBase, lightModeColor, railEdgeSoftness);

  gl_FragColor = vec4(antialiasedColor, 1.0);
}

uniform vec3 uAccentColor;
uniform float uOpacity;
uniform float uPatternBias;
uniform float uTravel;

varying vec2 vRailUv;

const float TAU = 6.28318530718;

void main() {
  float orbit = fract(vRailUv.y);
  float travel = fract(uTravel + sin((orbit + uTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.28, wrappedDistance);
  float laserCore = 1.0 - smoothstep(0.0, 0.14, wrappedDistance);
  float pulseBand = 0.5 + 0.5 * sin((orbit * 7.0 - travel * 4.5) * TAU);
  float edgeGlint =
    smoothstep(
      0.6,
      1.0,
      0.5 + 0.5 * sin((orbit * 11.0 - travel * 8.5) * TAU)
    ) *
    (0.18 + sweep * 0.82);
  float flare = laserCore * (0.7 + pulseBand * 0.46);
  float ember =
    0.58 + hotCore * 0.28 + pulseBand * 0.22 + flare * 0.34 + edgeGlint * 0.14;
  float cylindricalLift = 0.9 + 0.1 * sin(vRailUv.x * TAU);
  float intensity = clamp(
    uOpacity *
      (sweep * 0.34 + hotCore * 0.28 + flare * 0.42 + edgeGlint * 0.18) *
      ember *
      cylindricalLift,
    0.0,
    1.0
  );
  vec3 color =
    uAccentColor *
    (0.34 + sweep * 0.28 + hotCore * 0.38 + flare * 0.6 + edgeGlint * 0.24);
  vec3 moltenBase = uAccentColor * 0.34;
  vec3 lightModeColor = mix(moltenBase, color, intensity);
  float railEdgeSoftness =
    smoothstep(0.0, 0.18, vRailUv.x) *
    smoothstep(0.0, 0.18, 1.0 - vRailUv.x);
  vec3 antialiasedColor = mix(moltenBase, lightModeColor, railEdgeSoftness);

  gl_FragColor = vec4(antialiasedColor, 1.0);
}

attribute vec2 a_position;
void main() {
  gl_Position = vec4(a_position, 0.0, 1.0);
}

precision highp float;

uniform vec2 u_resolution;
uniform vec2 u_size;
uniform vec4 u_points[

];
uniform vec3 u_light;
uniform float u_time;

const vec3 cyan = vec3(54.0, 204.0, 255.0) / 255.0;
const vec3 lilac = vec3(168.0, 153.0, 255.0) / 255.0;
const vec3 pink = vec3(244.0, 180.0, 229.0) / 255.0;
const float spread = 6.8;
const float tunnelDepth = 0.8;

float gaussian(float x, float width) {
  return exp(-x * x / (width * width));
}

vec3 spectrum(float phase) {
  float cycle = 0.5 + 0.5 * sin(phase);
  return cycle < 0.5
    ? mix(cyan, lilac, cycle * 2.0)
    : mix(lilac, pink, cycle * 2.0 - 1.0);
}

// Refract the existing contour beams through a smooth tunnel around their
// shared source. Pixels and their contour anchors must use this same mapping.
vec2 tunnel(vec2 p) {
  vec2 delta = p - u_light.xy;
  float radius = length(delta);
  float aperture = 0.7;
  float travel = max(radius - aperture, 0.0);
  float reach = max(spread * 0.55, 1.0);
  float normalized = travel / reach;
  float progress = normalized * normalized / (1.0 + normalized * normalized);
  float angle = -0.05 * progress;
  float c = cos(angle);
  float s = sin(angle);
  vec2 rotated = vec2(c * delta.x + s * delta.y, -s * delta.x + c * delta.y);
  // Logarithmic perspective is monotonic at every setting: no folding,
  // repeated bends, or discontinuities as the source crosses a letter.
  float compressed = reach * log(1.0 + travel * tunnelDepth / reach) / tunnelDepth;
  float mappedRadius = min(radius, aperture) + compressed;
  return u_light.xy + rotated * mappedRadius / max(radius, 0.0001);
}

void main() {
  vec2 p = (gl_FragCoord.xy / u_resolution - 0.5) * u_size;
  vec2 fieldP = tunnel(p);
  float t = u_time;
  vec3 radiance = vec3(0.0);
  float density = 0.0;
  const float amplification = 3.5;

  // All rays share one moving light behind the text. Each contour point
  // projects away from that light, so cursor movement steers the whole field.
  for (int i = 0; i <

; i++) {
    vec4 point = u_points[i];
    if (point.z < 0.003) continue;
    // Map the fixed ink contour into the same space as the sampled pixel.
    // At p == point.xy, delta stays zero even after the light has moved away.
    // Leaving the anchor unwarped makes the visible root slide off its letter.
    vec2 origin = tunnel(point.xy);
    vec2 fromLight = origin - u_light.xy;
    float separation = length(fromLight);
    vec2 direction = fromLight / max(separation, 0.001);
    vec2 delta = fieldP - origin;
    float along = dot(delta, direction);
    float across = delta.x * direction.y - delta.y * direction.x;
    float distance = max(along, 0.0);
    float phase = point.w;

    // A single shallow bend near the outside; no waves along a ribbon.
    vec2 edgeReach = (u_size * 0.5 - sign(direction) * point.xy)
      / max(abs(direction), vec2(0.001));
    float reach = min(edgeReach.x, edgeReach.y);
    float onset = reach * (0.42 + 0.06 * sin(phase));
    float span = max(reach - onset, 0.5);
    float beyond = max(distance - onset, 0.0);
    // Ease through a straight beam when crossing an axis. A sign() here
    // flips the outer bend in a single frame even when the source is smooth.
    float curve = 2.0 * direction.x * direction.y * (0.3 + 0.07 * sin(phase * 1.7));
    curve *= (1.0 + 0.12 * sin(t * 0.27 + phase));
    float bend = curve * beyond * beyond / (2.0 * span);
    float slope = curve * beyond / span;
    across = (across - bend) / sqrt(1.0 + slope * slope);

    float width = (0.055 + distance * (0.15 + 0.03 * sin(phase * 2.1)));
    width *= (1.0 + 0.1 * sin(t * 0.3 + phase));
    float side = sin(phase * 1.3) < 0.0 ? -1.0 : 1.0;
    float sheet = gaussian(across - width * side * 0.4, width);
    float bloom = gaussian(across, width * 2.3 + 0.1);
    float rim = gaussian(across, (0.025 + distance * 0.018));
    float forward = smoothstep(-0.08, 0.22, along);
    float falloff = exp(-distance / (spread * 0.82));
    float flow = distance * 0.55 - t * 0.3 + phase;
    float power = point.z * forward * falloff * (0.9 + 0.1 * sin(flow));
    // A broad fade hides the rapid angular change as the light passes an
    // outline point; there is no hard distance cutoff that can flash a ray.
    power *= smoothstep(0.0, 0.28, separation);

    vec3 color = spectrum(t * 0.22 + phase * 0.4 + distance * 0.27);
    vec3 bodyColor = mix(color, vec3(0.9, 0.97, 1.0), 0.2);
    vec3 rimColor = mix(color, vec3(0.94, 0.99, 1.0), 0.8);
    // Concentrate the extra light inside the ribbons. Boosting the broad
    // haze equally washes out the blue gaps and hides their luminous cores.
    float body = (sheet * 0.32 * amplification + bloom * 0.09 * 1.35) * power;
    float core = gaussian(across - width * side * 0.4, width * 0.42);
    core *= 0.65 * power;
    float edge = rim * 0.17 * power * 2.2;
    float contact = exp(-dot(delta, delta) / 0.025) * point.z * 0.1 * amplification;
    radiance += bodyColor * body + rimColor * (edge + contact) + vec3(0.97, 0.99, 1.0) * core;
    density += body + edge + contact + core;
  }

  // A diffuse backlight also shows through counters such as O and U.
  // The visible letter sits in front of this continuous field.
  vec2 lightDelta = fieldP - u_light.xy;
  float glow = exp(-dot(lightDelta, lightDelta) / 0.65) * u_light.z * 0.48 * 2.2;
  float haze = exp(-dot(lightDelta, lightDelta) / 4.0) * u_light.z * 0.12;
  vec3 sourceColor = mix(cyan, spectrum(t * 0.22), 0.35);
  radiance += mix(sourceColor, vec3(0.93, 0.98, 1.0), 0.7) * glow + sourceColor * haze;
  density += glow + haze;

  vec3 color = radiance / max(density, 0.001);
  float alpha = (1.0 - exp(-density * 1.35));
  gl_FragColor = vec4(color * alpha, alpha);
}

