  vec2 curlGradient = vec2(abs(texture(derivatives, uv+x).g) - abs(texture(derivatives, uv-x).g),
    abs(texture(derivatives, uv+y).g) - abs(texture(derivatives, uv-y).g));
  vec2 n = curlGradient / max(length(curlGradient), 0.01);
  float curl = texture(derivatives, uv).g;
  vec2 v = texture(velocity, uv).xy - gradient + dt * 1.5 * curl * vec2(n.y, -n.x);
  color = vec4(v, 0.0, 1.0);
}

uniform sampler2D previousPigment;
uniform sampler2D currentPigment;
uniform float frameBlend;
uniform vec4 lens;
void main() {
  vec2 p = vec2(uv.x, 1.0 - uv.y) * box;
  vec2 fromLens = p - lens.xy;
  if (length(fromLens) < lens.z) p = lens.xy + fromLens / lens.w;
  vec2 q = p / box;
  color = vec4(mix(texture(previousPigment, q).rgb, texture(currentPigment, q).rgb, frameBlend), 1.0);
}

uniform int pigment;
void main() {
  color = pigment == 1 ? vec4(original(uv), 0.0) : vec4(resting(uv), 0.0, 1.0);
}

uniform sampler2D velocity;
uniform sampler2D previousPigment;
void main() {
  vec2 v = texture(velocity, uv).xy;
  vec2 midpoint = uv - 0.5 * dt * v / grid;
  vec2 from = uv - dt * texture(velocity, midpoint).xy / grid;
  vec4 carried = texture(previousPigment, from);
  // The alpha channel carries mixing history. Disturbed ink exchanges more slowly with the stock.
  float mixed = carried.a * exp(-0.48 * dt);
  vec3 stock = original(uv);
  float reservoir = pigmentStrength(stock);
  float exchange = mix(mix(0.53, 2.35, reservoir), 0.16, mixed);
  vec3 pigment = mix(carried.rgb, stock, 1.0 - exp(-exchange * dt));
  if (brush.w > 0.001) {
    vec2 r = fromStroke(uv);
    vec2 dir = normalize(brush.xy + vec2(0.001, 0.0));
    float side = dot(r, vec2(-dir.y, dir.x));
    float front = dot(r, dir);
    vec2 shoulder = vec2((front - 0.22) / 0.90, (abs(side) - 0.71) / 0.34);
    float contact = exp(-dot(shoulder, shoulder)) * brush.w;
    vec3 entrained = mix(firstInk, secondInk, smoothstep(-0.35, 0.35, side));
    pigment = mix(pigment, entrained, 1.0 - exp(-2.7 * dt * contact));
    mixed = mix(mixed, 1.0, 1.0 - exp(-6.0 * dt * contact));
  }
  color = vec4(pigment, mixed);
}

attribute vec2 a_position;
varying vec2 v_uv;

void main() {
  v_uv = a_position * 0.5 + 0.5;
  gl_Position = vec4(a_position, 0.0, 1.0);
}

uniform float u_edgeSoftness;
uniform float u_grain;
uniform float u_intensity;
uniform vec3 u_mist;
uniform vec3 u_primary;
uniform vec2 u_resolution;
uniform vec3 u_secondary;
uniform float u_speed;
uniform vec3 u_surface;
uniform float u_time;
uniform float u_warp;

varying vec2 v_uv;

float random(vec2 point) {
  vec3 point3 = fract(vec3(point.xyx) * 0.1031);
  point3 += dot(point3, point3.yzx + 33.33);
  return fract((point3.x + point3.y) * point3.z);
}

float noise(vec2 point) {
  vec2 cell = floor(point);
  vec2 local = fract(point);
  vec2 curve = local * local * (3.0 - 2.0 * local);

  float bottomLeft = random(cell);
  float bottomRight = random(cell + vec2(1.0, 0.0));
  float topLeft = random(cell + vec2(0.0, 1.0));
  float topRight = random(cell + vec2(1.0, 1.0));

  return mix(
    mix(bottomLeft, bottomRight, curve.x),
    mix(topLeft, topRight, curve.x),
    curve.y
  );
}

float fbm(vec2 point) {
  float value = 0.0;
  float amplitude = 0.52;
  mat2 rotation = mat2(0.80, -0.60, 0.60, 0.80);

  for (int octave = 0; octave < FBM_OCTAVES; octave++) {
    value += amplitude * noise(point);
    point = rotation * point * 2.03 + vec2(7.1, 3.7);
    amplitude *= 0.5;
  }

  return value;
}

void main() {
  vec2 uv = v_uv;
  float aspect = min(u_resolution.x / max(u_resolution.y, 1.0), 3.0);
  float motionTime = u_time * max(u_speed, 0.0);

  vec2 point = vec2(uv.x * (1.12 + aspect * 0.16), uv.y * 1.08);
  vec2 drift = vec2(
    motionTime * 0.34 + sin(motionTime * 0.41) * 0.12,
    -motionTime * 0.07 + cos(motionTime * 0.29) * 0.10
  );

  vec2 firstWarp = vec2(
    fbm(point * 1.05 + drift),
    fbm(point * 1.05 + drift + vec2(4.8, 1.7))
  );
  float secondField = fbm(
    point * 1.45 + firstWarp * (1.25 * u_warp) + vec2(1.4, 6.2)
  );
  vec2 secondWarp = vec2(
    secondField,
    noise(point * 1.25 + firstWarp * (1.1 * u_warp) + vec2(8.3, 2.1))
  );

  float pooledPigment = fbm(
    point * 1.18 + secondWarp * (1.7 * u_warp) + drift * 0.35
  );
  float broadWash = firstWarp.y;

  // One continuously warped lower boundary creates the broad painted wash.
  float boundary = 0.48;
  boundary += (secondWarp.x - 0.5) * 0.29;
  boundary += (broadWash - 0.5) * 0.17;
  boundary += sin(uv.x * 3.2 + motionTime * 0.72) * 0.035;

  float feather = u_edgeSoftness * mix(0.78, 1.25, broadWash);
  float wash = smoothstep(boundary - feather, boundary + feather, uv.y);

  float granulation = noise(
    point * 5.2 + secondWarp * 0.85 + drift * 1.3
  );
  float density = 0.98;
  density += (pooledPigment - 0.5) * 0.42;
  density += (broadWash - 0.5) * 0.28;
  density += (granulation - 0.5) * u_grain * 1.6;
  density *= mix(0.70, 1.08, smoothstep(0.25, 0.75, pooledPigment));

  float edgeDistance = (uv.y - boundary) / max(feather, 0.001);
  float wetEdge = exp(-edgeDistance * edgeDistance * 2.2) * 0.10;
  float opacity = clamp(
    (wash * density + wetEdge * wash) * u_intensity,
    0.0,
    1.0
  );

  float lowerPigment = smoothstep(boundary - 0.10, boundary + 0.24, uv.y);
  float upperPigment = smoothstep(0.67, 1.0, uv.y);
  vec3 pigment = mix(u_mist, u_secondary, lowerPigment);
  pigment = mix(pigment, u_primary, upperPigment * 0.86);
  pigment = mix(
    pigment,
    u_secondary,
    clamp((secondWarp.y - 0.55) * 0.24, 0.0, 0.12)
  );

  vec3 color = mix(u_surface, pigment, opacity);
  gl_FragColor = vec4(color, 1.0);
}

attribute float aDuration;
attribute float aGlyphIndex;
attribute float aLift;
attribute float aPhase;
attribute float aSize;
attribute float aTone;

uniform float uDevicePixelRatio;
uniform vec3 uFadeColor;
uniform float uGlyphCount;
uniform float uGlyphSize;
uniform vec3 uPalette[3];
uniform float uReducedMotion;
uniform float uSphereRadius;
uniform float uTime;
uniform vec2 uViewportSize;

varying float vAlpha;
varying float vGlyphIndex;
varying vec3 vColor;

void main() {
  float time = mix(uTime / max(aDuration, 1.0), 0.0, uReducedMotion);
  float progress = fract(aPhase + time);
  float rotation = mix(
    -0.022,
    0.205,
    progress
  );
  float shellRadius = uSphereRadius + aLift;
  float perspectiveSpread = mix(1.0, 1.028, progress);
  float horizontal = position.x * uViewportSize.x * perspectiveSpread;
  float ringRadius = sqrt(
    max(shellRadius * shellRadius - horizontal * horizontal, 1.0)
  );
  vec3 shellPosition = vec3(
    horizontal,
    ringRadius * cos(rotation),
    ringRadius * sin(rotation)
  );

  float emerge = smoothstep(0.035, 0.16, progress);
  float fade = 1.0 - smoothstep(0.62, 0.96, progress);
  float limbEnergy = mix(0.84, 1.0, smoothstep(0.08, 0.24, progress));
  float liveAlpha = emerge * fade * limbEnergy;
  float stillAlpha = 0.48 + 0.36 * sin(aPhase * 6.28318530718);
  vAlpha = mix(liveAlpha, max(stillAlpha, 0.22), uReducedMotion);

  float proximityScale = mix(0.74, 1.56, progress);
  gl_PointSize = clamp(
    uGlyphSize * aSize * proximityScale * max(uDevicePixelRatio, 1.0),
    1.0,
    48.0
  );
  gl_Position = projectionMatrix * modelViewMatrix * vec4(shellPosition, 1.0);

  int tone = int(aTone + 0.5);
  vec3 toneColor = uPalette[0];
  if (tone == 1) toneColor = uPalette[1];
  else if (tone == 2) toneColor = uPalette[2];

  vec3 crestColor = mix(uPalette[2], toneColor, 0.18);
  vec3 emberColor = mix(
    uPalette[1],
    uFadeColor,
    smoothstep(0.34, 0.94, progress)
  );
  vColor = mix(crestColor, emberColor, smoothstep(0.12, 0.88, progress));

  vGlyphIndex = mod(aGlyphIndex + floor(aPhase + time), uGlyphCount);
}

uniform sampler2D uAtlas;
uniform float uGlyphCount;

varying float vAlpha;
varying float vGlyphIndex;
varying vec3 vColor;

void main() {
  vec2 atlasUv = vec2(
    (vGlyphIndex + gl_PointCoord.x) / uGlyphCount,
    1.0 - gl_PointCoord.y
  );
  float ink = texture2D(uAtlas, atlasUv).a;
  float alpha = ink * vAlpha;

  if (alpha <= 0.025) discard;

  gl_FragColor = vec4(vColor, alpha);
}

varying vec3 vLocalPosition;

void main() {
  vLocalPosition = position;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

uniform vec3 uAccentColor;
uniform vec3 uGlowBaseColor;
uniform float uIntensity;
uniform float uOpacity;
uniform float uShadowMix;
uniform float uPatternBias;
uniform float uTravel;

varying vec3 vLocalPosition;

const float PI = 3.14159265359;
const float TAU = 6.28318530718;

void main() {
  float angle = atan(vLocalPosition.z, vLocalPosition.x);
  float orbit = fract((angle + PI) / TAU);
  float travel = fract(uTravel + sin((orbit + uTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.34, wrappedDistance);
  float pulseBand = 0.5 + 0.5 * sin((orbit * 7.0 - travel * 4.5) * TAU);
  float ember = 0.64 + hotCore * 0.42 + pulseBand * 0.34;
  float verticalLift = 0.84 + 0.16 * clamp(vLocalPosition.y + 0.5, 0.0, 1.0);
  float glow = 0.12 + sweep * 0.72 + hotCore * 0.32;
  float alpha = uOpacity * glow * ember * verticalLift;
  vec3 accentColor =
    uAccentColor * (0.82 + sweep * 0.62 + hotCore * 0.68) * uIntensity;
  vec3 color = mix(
    accentColor,
    mix(uGlowBaseColor, accentColor, hotCore),
    uShadowMix
  );

  gl_FragColor = vec4(clamp(color, 0.0, 1.0), alpha);
}

uniform vec3 uAccentColor;
uniform vec3 uGlowBaseColor;
uniform float uFacePhaseBias;
uniform float uFaceRimWidth;
uniform float uFaceVariant;
uniform float uOpacity;
uniform float uShadowMix;
uniform float uPatternBias;
uniform float uTravel;

varying vec3 vLocalPosition;

const float PI = 3.14159265359;
const float TAU = 6.28318530718;

void main() {
  float faceThreshold = 0.495;
  bool onXAxisFace = abs(vLocalPosition.x) >= faceThreshold;
  bool onYAxisFace = abs(vLocalPosition.y) >= faceThreshold;
  bool onZAxisFace = abs(vLocalPosition.z) >= faceThreshold;

  float xFaceRim = 1.0 - smoothstep(
    0.0,
    uFaceRimWidth,
    min(0.5 - abs(vLocalPosition.y), 0.5 - abs(vLocalPosition.z))
  );
  float yFaceRim = 1.0 - smoothstep(
    0.0,
    uFaceRimWidth,
    min(0.5 - abs(vLocalPosition.x), 0.5 - abs(vLocalPosition.z))
  );
  float zFaceRim = 1.0 - smoothstep(
    0.0,
    uFaceRimWidth,
    min(0.5 - abs(vLocalPosition.x), 0.5 - abs(vLocalPosition.y))
  );
  float faceBleed =
    (onXAxisFace ? xFaceRim : 0.0) +
    (onYAxisFace ? yFaceRim : 0.0) +
    (onZAxisFace ? zFaceRim : 0.0);
  faceBleed = min(faceBleed, 1.0);

  float angle = atan(vLocalPosition.z, vLocalPosition.x);
  float orbit = fract((angle + PI) / TAU);
  float faceTravel = fract(uTravel + uFacePhaseBias * uFaceVariant);
  float travel = fract(faceTravel + sin((orbit + faceTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.34, wrappedDistance);
  float pulseBand =
    0.5 +
    0.5 *
      sin(
        (
          orbit * 7.0 -
          travel * 4.5 +
          uFacePhaseBias * 1.7 * uFaceVariant
        ) *
          TAU
      );
  float ember = 0.62 + hotCore * 0.34 + pulseBand * 0.28;
  float verticalLift = 0.84 + 0.16 * clamp(vLocalPosition.y + 0.5, 0.0, 1.0);
  float alpha =
    uOpacity *
    faceBleed *
    (sweep * 0.74 + hotCore * 0.26) *
    ember *
    verticalLift;
  vec3 baseAccentColor =
    uAccentColor * (0.34 + sweep * 0.28 + hotCore * 0.34);
  vec3 radiantAccent = mix(
    uAccentColor,
    vec3(1.0, 0.78, 0.52),
    hotCore * 0.58
  );
  vec3 boostedAccentColor =
    radiantAccent * (0.48 + sweep * 0.56 + hotCore * 0.78);
  vec3 accentColor = mix(
    baseAccentColor,
    boostedAccentColor,
    uFaceVariant
  );
  vec3 color = mix(
    accentColor,
    mix(uGlowBaseColor, accentColor, hotCore),
    uShadowMix
  );

  gl_FragColor = vec4(clamp(color, 0.0, 1.0), alpha);
}

varying vec2 vRailUv;

void main() {
  vRailUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}

uniform vec3 uAccentColor;
uniform float uOpacity;
uniform float uPatternBias;
uniform float uTravel;

varying vec2 vRailUv;

const float TAU = 6.28318530718;

void main() {
  float orbit = fract(vRailUv.y);
  float travel = fract(uTravel + sin((orbit + uTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.26, wrappedDistance);
  float laserCore = 1.0 - smoothstep(0.0, 0.12, wrappedDistance);
  float pulseBand = 0.5 + 0.5 * sin((orbit * 7.0 - travel * 4.5) * TAU);
  float edgeGlint =
    smoothstep(
      0.58,
      1.0,
      0.5 + 0.5 * sin((orbit * 11.0 - travel * 8.5) * TAU)
    ) *
    (0.24 + sweep * 0.76);
  float flare = laserCore * (0.72 + pulseBand * 0.52);
  float ember =
    0.62 + hotCore * 0.34 + pulseBand * 0.26 + flare * 0.42 + edgeGlint * 0.18;
  float cylindricalLift = 0.94 + 0.06 * sin(vRailUv.x * TAU);
  float glow =
    0.1 + sweep * 0.58 + hotCore * 0.42 + flare * 0.66 + edgeGlint * 0.24;
  float intensity = clamp(
    uOpacity * glow * ember * cylindricalLift,
    0.0,
    1.0
  );
  vec3 color =
    uAccentColor *
    (0.78 + sweep * 0.48 + hotCore * 0.54 + flare * 0.88 + edgeGlint * 0.28);
  vec3 moltenBase = uAccentColor * 0.74;
  vec3 lightModeColor = mix(moltenBase, color, intensity);
  float railEdgeSoftness =
    smoothstep(0.0, 0.12, vRailUv.x) *
    smoothstep(0.0, 0.12, 1.0 - vRailUv.x);
  vec3 antialiasedColor = mix(moltenBase, lightModeColor, railEdgeSoftness);

  gl_FragColor = vec4(antialiasedColor, 1.0);
}

uniform vec3 uAccentColor;
uniform float uOpacity;
uniform float uPatternBias;
uniform float uTravel;

varying vec2 vRailUv;

const float TAU = 6.28318530718;

void main() {
  float orbit = fract(vRailUv.y);
  float travel = fract(uTravel + sin((orbit + uTravel) * TAU) * uPatternBias);
  float wrappedDistance = abs(orbit - travel);
  wrappedDistance = min(wrappedDistance, 1.0 - wrappedDistance);

  float sweep = 1.0 - smoothstep(0.0, 2.4, wrappedDistance);
  float hotCore = 1.0 - smoothstep(0.0, 0.28, wrappedDistance);
  float laserCore = 1.0 - smoothstep(0.0, 0.14, wrappedDistance);
  float pulseBand = 0.5 + 0.5 * sin((orbit * 7.0 - travel * 4.5) * TAU);
  float edgeGlint =
    smoothstep(
      0.6,
      1.0,
      0.5 + 0.5 * sin((orbit * 11.0 - travel * 8.5) * TAU)
    ) *
    (0.18 + sweep * 0.82);
  float flare = laserCore * (0.7 + pulseBand * 0.46);
  float ember =
    0.58 + hotCore * 0.28 + pulseBand * 0.22 + flare * 0.34 + edgeGlint * 0.14;
  float cylindricalLift = 0.9 + 0.1 * sin(vRailUv.x * TAU);
  float intensity = clamp(
    uOpacity *
      (sweep * 0.34 + hotCore * 0.28 + flare * 0.42 + edgeGlint * 0.18) *
      ember *
      cylindricalLift,
    0.0,
    1.0
  );
  vec3 color =
    uAccentColor *
    (0.34 + sweep * 0.28 + hotCore * 0.38 + flare * 0.6 + edgeGlint * 0.24);
  vec3 moltenBase = uAccentColor * 0.34;
  vec3 lightModeColor = mix(moltenBase, color, intensity);
  float railEdgeSoftness =
    smoothstep(0.0, 0.18, vRailUv.x) *
    smoothstep(0.0, 0.18, 1.0 - vRailUv.x);
  vec3 antialiasedColor = mix(moltenBase, lightModeColor, railEdgeSoftness);

  gl_FragColor = vec4(antialiasedColor, 1.0);
}

attribute vec2 a_position;
void main() {
  gl_Position = vec4(a_position, 0.0, 1.0);
}

precision highp float;

uniform vec2 u_resolution;
uniform vec2 u_size;
uniform vec4 u_points[

];
uniform vec3 u_light;
uniform float u_time;

const vec3 cyan = vec3(54.0, 204.0, 255.0) / 255.0;
const vec3 lilac = vec3(168.0, 153.0, 255.0) / 255.0;
const vec3 pink = vec3(244.0, 180.0, 229.0) / 255.0;
const float spread = 6.8;
const float tunnelDepth = 0.8;

float gaussian(float x, float width) {
  return exp(-x * x / (width * width));
}

vec3 spectrum(float phase) {
  float cycle = 0.5 + 0.5 * sin(phase);
  return cycle < 0.5
    ? mix(cyan, lilac, cycle * 2.0)
    : mix(lilac, pink, cycle * 2.0 - 1.0);
}

// Refract the existing contour beams through a smooth tunnel around their
// shared source. Pixels and their contour anchors must use this same mapping.
vec2 tunnel(vec2 p) {
  vec2 delta = p - u_light.xy;
  float radius = length(delta);
  float aperture = 0.7;
  float travel = max(radius - aperture, 0.0);
  float reach = max(spread * 0.55, 1.0);
  float normalized = travel / reach;
  float progress = normalized * normalized / (1.0 + normalized * normalized);
  float angle = -0.05 * progress;
  float c = cos(angle);
  float s = sin(angle);
  vec2 rotated = vec2(c * delta.x + s * delta.y, -s * delta.x + c * delta.y);
  // Logarithmic perspective is monotonic at every setting: no folding,
  // repeated bends, or discontinuities as the source crosses a letter.
  float compressed = reach * log(1.0 + travel * tunnelDepth / reach) / tunnelDepth;
  float mappedRadius = min(radius, aperture) + compressed;
  return u_light.xy + rotated * mappedRadius / max(radius, 0.0001);
}

void main() {
  vec2 p = (gl_FragCoord.xy / u_resolution - 0.5) * u_size;
  vec2 fieldP = tunnel(p);
  float t = u_time;
  vec3 radiance = vec3(0.0);
  float density = 0.0;
  const float amplification = 3.5;

  // All rays share one moving light behind the text. Each contour point
  // projects away from that light, so cursor movement steers the whole field.
  for (int i = 0; i <

; i++) {
    vec4 point = u_points[i];
    if (point.z < 0.003) continue;
    // Map the fixed ink contour into the same space as the sampled pixel.
    // At p == point.xy, delta stays zero even after the light has moved away.
    // Leaving the anchor unwarped makes the visible root slide off its letter.
    vec2 origin = tunnel(point.xy);
    vec2 fromLight = origin - u_light.xy;
    float separation = length(fromLight);
    vec2 direction = fromLight / max(separation, 0.001);
    vec2 delta = fieldP - origin;
    float along = dot(delta, direction);
    float across = delta.x * direction.y - delta.y * direction.x;
    float distance = max(along, 0.0);
    float phase = point.w;

    // A single shallow bend near the outside; no waves along a ribbon.
    vec2 edgeReach = (u_size * 0.5 - sign(direction) * point.xy)
      / max(abs(direction), vec2(0.001));
    float reach = min(edgeReach.x, edgeReach.y);
    float onset = reach * (0.42 + 0.06 * sin(phase));
    float span = max(reach - onset, 0.5);
    float beyond = max(distance - onset, 0.0);
    // Ease through a straight beam when crossing an axis. A sign() here
    // flips the outer bend in a single frame even when the source is smooth.
    float curve = 2.0 * direction.x * direction.y * (0.3 + 0.07 * sin(phase * 1.7));
    curve *= (1.0 + 0.12 * sin(t * 0.27 + phase));
    float bend = curve * beyond * beyond / (2.0 * span);
    float slope = curve * beyond / span;
    across = (across - bend) / sqrt(1.0 + slope * slope);

    float width = (0.055 + distance * (0.15 + 0.03 * sin(phase * 2.1)));
    width *= (1.0 + 0.1 * sin(t * 0.3 + phase));
    float side = sin(phase * 1.3) < 0.0 ? -1.0 : 1.0;
    float sheet = gaussian(across - width * side * 0.4, width);
    float bloom = gaussian(across, width * 2.3 + 0.1);
    float rim = gaussian(across, (0.025 + distance * 0.018));
    float forward = smoothstep(-0.08, 0.22, along);
    float falloff = exp(-distance / (spread * 0.82));
    float flow = distance * 0.55 - t * 0.3 + phase;
    float power = point.z * forward * falloff * (0.9 + 0.1 * sin(flow));
    // A broad fade hides the rapid angular change as the light passes an
    // outline point; there is no hard distance cutoff that can flash a ray.
    power *= smoothstep(0.0, 0.28, separation);

    vec3 color = spectrum(t * 0.22 + phase * 0.4 + distance * 0.27);
    vec3 bodyColor = mix(color, vec3(0.9, 0.97, 1.0), 0.2);
    vec3 rimColor = mix(color, vec3(0.94, 0.99, 1.0), 0.8);
    // Concentrate the extra light inside the ribbons. Boosting the broad
    // haze equally washes out the blue gaps and hides their luminous cores.
    float body = (sheet * 0.32 * amplification + bloom * 0.09 * 1.35) * power;
    float core = gaussian(across - width * side * 0.4, width * 0.42);
    core *= 0.65 * power;
    float edge = rim * 0.17 * power * 2.2;
    float contact = exp(-dot(delta, delta) / 0.025) * point.z * 0.1 * amplification;
    radiance += bodyColor * body + rimColor * (edge + contact) + vec3(0.97, 0.99, 1.0) * core;
    density += body + edge + contact + core;
  }

  // A diffuse backlight also shows through counters such as O and U.
  // The visible letter sits in front of this continuous field.
  vec2 lightDelta = fieldP - u_light.xy;
  float glow = exp(-dot(lightDelta, lightDelta) / 0.65) * u_light.z * 0.48 * 2.2;
  float haze = exp(-dot(lightDelta, lightDelta) / 4.0) * u_light.z * 0.12;
  vec3 sourceColor = mix(cyan, spectrum(t * 0.22), 0.35);
  radiance += mix(sourceColor, vec3(0.93, 0.98, 1.0), 0.7) * glow + sourceColor * haze;
  density += glow + haze;

  vec3 color = radiance / max(density, 0.001);
  float alpha = (1.0 - exp(-density * 1.35));
  gl_FragColor = vec4(color * alpha, alpha);
}

varying vec2 vUv;

void main() {
  vUv = uv;
  gl_Position = vec4(position.xy, 1.0, 1.0);
}

uniform sampler2D starMap;
uniform float starExposure;
uniform float brightness;
uniform vec2 uvCenter;
uniform vec2 uvScale;

varying vec2 vUv;

void main() {
  vec2 plateUv = (vUv - vec2(0.5)) * uvScale + uvCenter;
  vec3 color = max(
    texture2D(starMap, plateUv).rgb - vec3(0.0001),
    vec3(0.0)
  ) * starExposure * brightness;
  gl_FragColor = vec4(color, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}

vec2 remapEarthUv(vec2 uv) {
  // Preserve the scientific equirectangular projection. Composition is
  // authored by rotating the physical sphere, never by stretching or
  // repeating geography in UV space.
  // The sphere geometry duplicates vertices along the 0/1 longitude seam.
  // Preserve the raw longitude so RepeatWrapping can filter continuously
  // across that seam without introducing a fract/mod derivative break.
  return vec2(uv.x, clamp(uv.y, 0.001, 0.999));
}

vec4 sampleTextureDetailed(
  sampler2D textureMap,
  vec2 uv,
  vec2 texelSize,
  float lodBias,
  float detailStrength
) {
  vec4 center = texture2D(textureMap, uv, lodBias);
  if (detailStrength <= 0.0) return center;

  vec4 axialAverage = (
    texture2D(textureMap, uv + vec2(texelSize.x, 0.0), lodBias) +
    texture2D(textureMap, uv - vec2(texelSize.x, 0.0), lodBias) +
    texture2D(textureMap, uv + vec2(0.0, texelSize.y), lodBias) +
    texture2D(textureMap, uv - vec2(0.0, texelSize.y), lodBias)
  ) * 0.25;

  return clamp(center + (center - axialAverage) * detailStrength, 0.0, 1.0);
}

vec3 sampleEarthAlbedoDetailed(
  sampler2D textureMap,
  vec2 uv,
  vec2 texelSize,
  float lodBias,
  float detailStrength,
  float detailMask
) {
  vec3 center = texture2D(textureMap, uv, lodBias).rgb;
  vec2 uvRight = vec2(uv.x + texelSize.x, uv.y);
  vec2 uvLeft = vec2(uv.x - texelSize.x, uv.y);
  vec2 uvUp = vec2(uv.x, min(uv.y + texelSize.y, 0.999));
  vec2 uvDown = vec2(uv.x, max(uv.y - texelSize.y, 0.001));
  vec3 axialAverage = (
    texture2D(textureMap, uvRight, lodBias).rgb +
    texture2D(textureMap, uvLeft, lodBias).rgb +
    texture2D(textureMap, uvUp, lodBias).rgb +
    texture2D(textureMap, uvDown, lodBias).rgb
  ) * 0.25;

  // Adjust luminance only. Per-channel unsharp masking creates false colour
  // along coastlines after texture compression, while a restrained scalar
  // delta keeps the source chroma and photographed surface character.
  const vec3 luminanceWeights = vec3(0.2126, 0.7152, 0.0722);
  float centerLuminance = dot(center, luminanceWeights);
  float averageLuminance = dot(axialAverage, luminanceWeights);
  float localContrast = clamp(
    centerLuminance - averageLuminance,
    -0.055,
    0.055
  );
  return clamp(
    center + vec3(localContrast * detailStrength * detailMask),
    0.0,
    1.0
  );
}

float remapCloudDensity(float cloudSample) {
  // Preserve the fine filament field in the NASA cloud map. The previous
  // high threshold retained only storm cores, turning weather systems into
  // sparse grey decals instead of a translucent optical-depth layer.
  float wisps = smoothstep(0.035, 0.38, cloudSample) * 0.075;
  float core = pow(smoothstep(0.12, 0.76, cloudSample), 1.32);
  return clamp(wisps + core * 0.86, 0.0, 1.0);
}

varying vec2 vUv;
varying vec3 vWorldBitangent;
varying vec3 vWorldNormal;
varying vec3 vWorldPosition;
varying vec3 vWorldTangent;

void main() {
  vUv = uv;
  vec3 objectNormal = normalize(normal);
  vec3 objectTangent = vec3(objectNormal.z, 0.0, -objectNormal.x);
  if (dot(objectTangent, objectTangent) < 0.0001) {
    objectTangent = vec3(1.0, 0.0, 0.0);
  }
  objectTangent = normalize(objectTangent);
  vec3 objectBitangent = normalize(cross(objectNormal, objectTangent));
  mat3 worldTransform = mat3(modelMatrix);
  vWorldNormal = normalize(worldTransform * objectNormal);
  vWorldTangent = normalize(worldTransform * objectTangent);
  vWorldBitangent = normalize(worldTransform * objectBitangent);
  vec4 worldPosition = modelMatrix * vec4(position, 1.0);
  vWorldPosition = worldPosition.xyz;
  gl_Position = projectionMatrix * viewMatrix * worldPosition;
}

uniform sampler2D albedoMap;
uniform sampler2D earthDataMap;
uniform sampler2D cloudMap;
uniform vec2 albedoTexelSize;
uniform vec2 earthDataTexelSize;
uniform vec3 sunDirection;
uniform vec3 nightFill;
uniform vec2 cloudOffset;
uniform vec2 cloudTexelSize;
uniform float textureLodBias;
uniform float detailStrength;
uniform float cloudDetailStrength;
uniform float daylightStrength;
uniform float cityLightStrength;
uniform float cloudShadowStrength;
uniform float oceanSpecularStrength;
uniform float terrainReliefStrength;

varying vec2 vUv;
varying vec3 vWorldBitangent;
varying vec3 vWorldNormal;
varying vec3 vWorldPosition;
varying vec3 vWorldTangent;

void main() {
  vec3 normal = normalize(vWorldNormal);
  vec3 viewDirection = normalize(cameraPosition - vWorldPosition);
  vec3 lightDirection = sunDirection;
  float geometricViewDot = max(dot(normal, viewDirection), 0.0);
  float geometricSolarDot = dot(normal, lightDirection);
  vec2 surfaceUv = remapEarthUv(vUv);
  // Let the hardware choose the scientific mask's mip from screen-space
  // derivatives. A negative bias makes one-pixel coastlines crawl and turn
  // into hard map cut-outs at this deliberately grazing camera angle.
  float earthDataLodBias = 0.0;
  vec4 earthData = texture2D(
    earthDataMap,
    surfaceUv,
    earthDataLodBias
  );
  vec2 earthDataUvRight = vec2(
    surfaceUv.x + earthDataTexelSize.x,
    surfaceUv.y
  );
  vec2 earthDataUvLeft = vec2(
    surfaceUv.x - earthDataTexelSize.x,
    surfaceUv.y
  );
  vec2 earthDataUvUp = vec2(
    surfaceUv.x,
    min(surfaceUv.y + earthDataTexelSize.y, 0.999)
  );
  vec2 earthDataUvDown = vec2(
    surfaceUv.x,
    max(surfaceUv.y - earthDataTexelSize.y, 0.001)
  );
  vec4 earthDataRight = texture2D(
    earthDataMap,
    earthDataUvRight,
    earthDataLodBias
  );
  vec4 earthDataLeft = texture2D(
    earthDataMap,
    earthDataUvLeft,
    earthDataLodBias
  );
  vec4 earthDataUp = texture2D(
    earthDataMap,
    earthDataUvUp,
    earthDataLodBias
  );
  vec4 earthDataDown = texture2D(
    earthDataMap,
    earthDataUvDown,
    earthDataLodBias
  );
  float cityLights = earthData.r;
  float cityLocalAverage = (
    earthDataRight.r +
    earthDataLeft.r +
    earthDataUp.r +
    earthDataDown.r
  ) * 0.25;
  float ocean = smoothstep(0.22, 0.78, earthData.g);
  float landMask = 1.0 - ocean;
  float landRoughness = mix(0.76, 0.18, ocean);
  float maximumLocalOcean = max(
    max(max(earthData.g, earthDataRight.g), earthDataLeft.g),
    max(earthDataUp.g, earthDataDown.g)
  );
  float minimumLocalOcean = min(
    min(min(earthData.g, earthDataRight.g), earthDataLeft.g),
    min(earthDataUp.g, earthDataDown.g)
  );
  float interiorLand = 1.0 - smoothstep(0.015, 0.22, maximumLocalOcean);
  float coastVariation = maximumLocalOcean - minimumLocalOcean;
  float coastSafety = 1.0 - smoothstep(0.015, 0.12, coastVariation);
  float facingDetail = smoothstep(0.1, 0.42, geometricViewDot);
  float landDetailMask = interiorLand * coastSafety * facingDetail;
  vec3 sourceAlbedo = sampleEarthAlbedoDetailed(
    albedoMap,
    surfaceUv,
    albedoTexelSize,
    textureLodBias,
    detailStrength,
    landDetailMask
  );
  // NOAA ETOPO normals are packed into B/A as tangent-space X/Y. X points
  // east along +U and Y points north along +V; the positive Z component is
  // reconstructed so the scientific surface never changes the geometric
  // horizon or displaces the sphere.
  vec2 terrainNormalXY = earthData.ba * 2.0 - 1.0;
  float terrainNormalZ = sqrt(
    max(1.0 - dot(terrainNormalXY, terrainNormalXY), 0.0)
  );
  vec3 terrainWorldNormal = normalize(
    normalize(vWorldTangent) * terrainNormalXY.x +
      normalize(vWorldBitangent) * terrainNormalXY.y +
      normal * terrainNormalZ
  );
  normal = normalize(
    mix(normal, terrainWorldNormal, terrainReliefStrength * landMask)
  );
  float solarDot = dot(normal, lightDirection);
  float lambert = max((solarDot + 0.12) / 1.12, 0.0);
  float night = 1.0 - smoothstep(-0.1, 0.08, geometricSolarDot);
  float cloudSample = sampleTextureDetailed(
    cloudMap,
    surfaceUv + cloudOffset + vec2(0.0035, -0.0015),
    cloudTexelSize,
    textureLodBias * 0.8,
    cloudDetailStrength
  ).r;
  float clouds = remapCloudDensity(cloudSample);
  float cloudMacroDensity = texture2D(
    cloudMap,
    surfaceUv + cloudOffset + vec2(0.0035, -0.0015),
    textureLodBias * 0.8 + 4.0
  ).r;
  clouds *= mix(
    0.12,
    1.0,
    smoothstep(0.08, 0.28, cloudMacroDensity)
  );

  float albedoLuminance = dot(sourceAlbedo, vec3(0.2126, 0.7152, 0.0722));
  vec3 landAlbedo = mix(vec3(albedoLuminance), sourceAlbedo, 0.5);
  landAlbedo = pow(
    max(landAlbedo * vec3(0.9, 0.93, 0.99), 0.0),
    vec3(0.97)
  );
  vec3 oceanAlbedo = mix(
    vec3(0.006, 0.018, 0.042),
    sourceAlbedo * vec3(0.27, 0.35, 0.48),
    0.42
  );
  vec3 albedo = mix(landAlbedo, oceanAlbedo, ocean);

  float cloudShadow = 1.0 - clouds * cloudShadowStrength *
    smoothstep(-0.01, 0.1, solarDot);
  vec3 neutralDaylight = vec3(1.0, 0.985, 0.965) *
    lambert * daylightStrength * cloudShadow;
  float surfaceContactAlignment = pow(
    max(dot(viewDirection, -lightDirection), 0.0),
    12.0
  );
  float dawnScatter = smoothstep(-0.34, 0.04, solarDot) *
    (1.0 - smoothstep(0.2, 0.5, solarDot));
  vec3 dawnScatterColor = mix(
    vec3(0.12, 0.22, 0.44),
    vec3(0.95, 0.38, 0.1),
    surfaceContactAlignment
  );
  // Keep the anti-solar hemisphere truly dark. Readable cool fill belongs
  // only to the broad geometric twilight band, not to the full globe.
  float twilight = smoothstep(-0.42, -0.02, geometricSolarDot) *
    (1.0 - smoothstep(0.08, 0.3, geometricSolarDot));
  float twilightExposure = 0.28 + min(daylightStrength * 0.065, 0.55);
  vec3 twilightIrradiance = vec3(0.055, 0.09, 0.17) *
    twilight * twilightExposure;
  vec3 surfaceIrradiance = nightFill + neutralDaylight +
    twilightIrradiance +
    dawnScatterColor * dawnScatter * daylightStrength * 0.055;
  vec3 surface = albedo * surfaceIrradiance;

  // The ocean is mostly a reflection source at orbital grazing angles. A
  // small cool sky term keeps water legible in the photographic twilight
  // without turning the whole atmosphere into a blue emissive shell.
  float oceanFresnel = pow(
    1.0 - max(dot(normal, viewDirection), 0.0),
    3.0
  );
  vec3 skyReflection = vec3(0.006, 0.024, 0.064) *
    mix(0.28, 1.0, oceanFresnel) * ocean;
  float oceanTwilightVisibility = smoothstep(
    -0.38,
    0.08,
    geometricSolarDot
  );
  surface += skyReflection * smoothstep(-0.12, 0.28, geometricSolarDot);
  surface += ocean * vec3(0.004, 0.014, 0.042) *
    mix(0.4, 1.0, oceanFresnel) * oceanTwilightVisibility;

  float warmTerminator = smoothstep(-0.035, 0.01, solarDot) *
    (1.0 - smoothstep(0.065, 0.18, solarDot));
  surface += albedo * vec3(1.0, 0.38, 0.12) *
    warmTerminator * surfaceContactAlignment * daylightStrength * 0.14;

  float cityHighPass = max(cityLights - cityLocalAverage, 0.0);
  float cityDetail = smoothstep(0.002, 0.045, cityHighPass);
  float citySeed = smoothstep(0.08, 0.7, cityLights);
  float cityMask = pow(citySeed, 2.2) * cityDetail;
  vec3 cityEmission = vec3(1.0, 0.62, 0.24) *
    cityMask * night * cityLightStrength;

  vec3 halfDirection = normalize(lightDirection + viewDirection);
  float halfDot = max(dot(normal, halfDirection), 0.0);
  float tightGlint = pow(halfDot, 210.0);
  float broadGlint = pow(halfDot, 34.0) * 0.2;
  float glint = tightGlint + broadGlint;
  float viewFresnel = pow(1.0 - max(dot(normal, viewDirection), 0.0), 5.0);
  glint *= ocean * lambert * oceanSpecularStrength;
  glint *= mix(0.72, 0.38, landRoughness);
  glint *= mix(0.42, 1.0, viewFresnel);
  glint *= 1.0 - clouds * 0.7;

  vec3 glintColor = mix(
    vec3(1.0, 0.58, 0.28),
    vec3(1.0, 0.95, 0.84),
    smoothstep(0.015, 0.34, solarDot)
  );
  float aerialPerspective = pow(
    1.0 - max(dot(normal, viewDirection), 0.0),
    3.0
  ) * smoothstep(-0.08, 0.32, solarDot);
  vec3 dayHaze = vec3(0.018, 0.055, 0.12) * daylightStrength * 0.18;
  // Extinction through the near-tangent atmosphere suppresses map detail
  // before the solid night-side silhouette. The geometric normal keeps this
  // rolloff perfectly smooth even when ETOPO relief perturbs direct light.
  float antiSolarWeight = 1.0 - smoothstep(
    -0.18,
    0.025,
    geometricSolarDot
  );
  float nightLimbTransmission = smoothstep(
    0.025,
    0.22,
    geometricViewDot
  );
  float surfaceTransmission = mix(
    1.0,
    nightLimbTransmission,
    antiSolarWeight
  );
  vec3 surfaceRadiance = (surface + cityEmission) * surfaceTransmission +
    glintColor * glint;
  vec3 color = mix(
    surfaceRadiance,
    dayHaze,
    aerialPerspective * 0.22
  );
  // The inner atmosphere is painted onto the solid globe so it remains
  // inside the geographic silhouette. A broad blue Fresnel band rolls into
  // a tighter cyan edge, matching the layered horizon in orbital imagery.
  float innerAtmosphereFresnel = pow(1.0 - geometricViewDot, 4.5);
  float innerAtmosphereCore = pow(1.0 - geometricViewDot, 18.0);
  float innerAtmosphereDay = mix(
    0.34,
    1.0,
    smoothstep(-0.22, 0.18, geometricSolarDot)
  );
  vec3 innerAtmosphereColor = mix(
    vec3(0.025, 0.2, 0.82),
    vec3(0.42, 0.95, 1.55),
    innerAtmosphereCore
  );
  color += innerAtmosphereColor *
    (innerAtmosphereFresnel * 0.09 + innerAtmosphereCore * 0.2) *
    innerAtmosphereDay;
  gl_FragColor = vec4(color, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}

uniform sampler2D cloudMap;
uniform vec3 sunDirection;
uniform vec2 cloudTexelSize;
uniform float opacity;
uniform float solarStrength;
uniform float cloudDetailStrength;
uniform float textureLodBias;
uniform float sunriseProgress;

varying vec2 vUv;
varying vec3 vWorldBitangent;
varying vec3 vWorldNormal;
varying vec3 vWorldPosition;
varying vec3 vWorldTangent;

void main() {
  vec2 surfaceUv = remapEarthUv(vUv);
  float cloudSample = sampleTextureDetailed(
    cloudMap,
    surfaceUv,
    cloudTexelSize,
    textureLodBias * 0.8,
    cloudDetailStrength
  ).r;
  float density = remapCloudDensity(cloudSample);
  float cloudMacroDensity = texture2D(
    cloudMap,
    surfaceUv,
    textureLodBias * 0.8 + 4.0
  ).r;
  density *= mix(
    0.12,
    1.0,
    smoothstep(0.08, 0.28, cloudMacroDensity)
  );
  float cloudRight = texture2D(
    cloudMap,
    surfaceUv + vec2(cloudTexelSize.x, 0.0),
    textureLodBias * 0.8
  ).r;
  float cloudLeft = texture2D(
    cloudMap,
    surfaceUv - vec2(cloudTexelSize.x, 0.0),
    textureLodBias * 0.8
  ).r;
  float cloudUp = texture2D(
    cloudMap,
    surfaceUv + vec2(0.0, cloudTexelSize.y),
    textureLodBias * 0.8
  ).r;
  float cloudDown = texture2D(
    cloudMap,
    surfaceUv - vec2(0.0, cloudTexelSize.y),
    textureLodBias * 0.8
  ).r;
  float localAverage = (cloudRight + cloudLeft + cloudUp + cloudDown) * 0.25;
  float localDetail = clamp(abs(cloudSample - localAverage) * 3.6, 0.0, 1.0);
  density *= mix(0.96, 1.08, localDetail);
  float lightwardDensity = remapCloudDensity(
    texture2D(
      cloudMap,
      surfaceUv + vec2(0.0024, -0.0011),
      textureLodBias * 0.8
    ).r
  );
  vec3 normal = normalize(
    vWorldNormal +
      normalize(vWorldTangent) * (cloudRight - cloudLeft) * 0.11 +
      normalize(vWorldBitangent) * (cloudUp - cloudDown) * 0.11
  );
  vec3 viewDirection = normalize(cameraPosition - vWorldPosition);
  float geometricViewDot = max(
    dot(normalize(vWorldNormal), viewDirection),
    0.0
  );
  float solarDot = dot(normal, sunDirection);
  float diffuse = max(solarDot, 0.0);
  // Cloud tops receive dawn light before the solid surface below them. A
  // slightly wrapped transition keeps high weather systems legible across
  // the geometric terminator without adding global emissive fill.
  float day = smoothstep(-0.09, 0.12, solarDot);
  float dawnIllumination = smoothstep(0.08, 0.72, sunriseProgress);
  float viewDot = max(dot(normal, viewDirection), 0.0);
  // Most weather fades at the shell tangent. Only genuinely dense cloud
  // cores retain a trace of opacity there, breaking the otherwise perfect
  // sphere without turning wisps into a bright second outline.
  float edgeFeather = smoothstep(0.0, 0.0065, geometricViewDot);
  float denseCloudCore = smoothstep(0.52, 0.82, cloudSample);
  float tangentCoreOpacity = denseCloudCore *
    pow(1.0 - geometricViewDot, 18.0) * 0.09;
  float limbOpacity = min(1.0, edgeFeather + tangentCoreOpacity);

  vec3 coolShadow = vec3(0.018, 0.022, 0.03);
  vec3 whiteDaylight = vec3(0.96, 0.975, 1.0) *
    (0.21 + diffuse * solarStrength * 1.55);
  vec3 color = mix(coolShadow, whiteDaylight, day * dawnIllumination);
  float signedCloudDetail = clamp(
    (cloudSample - localAverage) * 3.0,
    -0.06,
    0.08
  );
  color *= 1.0 + signedCloudDetail;
  float cloudForwardScatter = pow(
    max(dot(viewDirection, -sunDirection), 0.0),
    14.0
  );
  float cloudSelfShadow = density * smoothstep(0.18, 0.78, lightwardDensity);
  float silverEdge = smoothstep(0.025, 0.28, density - lightwardDensity);
  color *= 1.0 - cloudSelfShadow * day * dawnIllumination * 0.3;
  color += vec3(1.0, 0.76, 0.48) * silverEdge * day *
    dawnIllumination * solarStrength * 0.82;

  float limb = pow(1.0 - viewDot, 9.0);
  float warmSilverLining = smoothstep(-0.018, 0.006, solarDot) *
    (1.0 - smoothstep(0.04, 0.1, solarDot));
  color += vec3(1.0, 0.42, 0.14) * limb * warmSilverLining *
    solarStrength * 0.36;
  color += vec3(1.0, 0.62, 0.28) * cloudForwardScatter *
    day * dawnIllumination * solarStrength * 0.62;

  float alpha = density * opacity *
    mix(0.54, 1.0, day * dawnIllumination) *
    limbOpacity;
  if (alpha < 0.003) discard;
  gl_FragColor = vec4(color, alpha);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}

uniform vec3 sunDirection;
uniform float intensity;
uniform float solarVisibility;

varying vec3 vWorldNormal;
varying vec3 vWorldPosition;

void main() {
  vec3 normal = normalize(vWorldNormal);
  vec3 viewDirection = normalize(cameraPosition - vWorldPosition);
  vec3 lightDirection = sunDirection;
  float viewDot = max(dot(normal, viewDirection), 0.0);
  float broadLimb = pow(1.0 - viewDot, 8.0);
  float coreLimb = pow(1.0 - viewDot, 22.0);
  // These bell-shaped Fresnel lobes peak just inside the expanded shell's
  // silhouette. Unlike a simple edge power, they remain wide enough to be
  // visible outside the solid Earth instead of collapsing to a subpixel.
  float outerAtmosphereFresnel = smoothstep(0.025, 0.12, viewDot) *
    (1.0 - smoothstep(0.28, 0.58, viewDot));
  float outerAtmosphereCore = smoothstep(0.045, 0.13, viewDot) *
    (1.0 - smoothstep(0.19, 0.36, viewDot));
  float edgeFeather = smoothstep(0.0, 0.028, viewDot);
  float solarDot = dot(normal, lightDirection);
  float day = smoothstep(-0.055, 0.1, solarDot);
  float warmContact = smoothstep(-0.022, 0.005, solarDot) *
    (1.0 - smoothstep(0.03, 0.09, solarDot));
  float forwardScatter = pow(max(dot(viewDirection, -lightDirection), 0.0), 22.0);
  float contactAlignment = pow(
    max(dot(viewDirection, -lightDirection), 0.0),
    6.2
  );
  float visibleSun = mix(0.15, 1.0, solarVisibility);

  vec3 rayleighColor = mix(
    vec3(0.08, 0.3, 0.82),
    vec3(0.5, 0.78, 1.15),
    coreLimb
  );
  float blueOpacity = clamp(
    (broadLimb * 0.13 + coreLimb * 0.48) * day * intensity * edgeFeather,
    0.0,
    0.075
  );
  vec3 mieColor = vec3(2.05, 0.52, 0.1);
  float warmOpacity = clamp(
    (broadLimb * warmContact * contactAlignment * 1.18 +
      forwardScatter * 0.055) *
      visibleSun * intensity * edgeFeather,
    0.0,
    0.17
  );
  vec3 color = rayleighColor * blueOpacity + mieColor * warmOpacity;
  float outerFresnelStrength = outerAtmosphereFresnel * intensity *
    mix(0.11, 0.24, day);
  float outerCoreStrength = outerAtmosphereCore * intensity *
    mix(0.2, 0.46, day);
  color += vec3(0.015, 0.2, 1.1) * outerFresnelStrength;
  // Keep the cyan core bright enough to feed bloom on composer tiers while
  // renderer tone mapping contains it on tier one.
  color += vec3(0.28, 1.35, 4.6) * outerCoreStrength;
  // A real atmosphere remains barely visible on the unlit limb. Keeping
  // this core-only and nearly neutral avoids an emissive blue bubble.
  float nightCore = pow(1.0 - viewDot, 25.0);
  float nightWeight = mix(1.0, 0.32, day);
  float nightEdgeFeather = smoothstep(0.0, 0.014, viewDot);
  vec3 nightAirglow = vec3(0.0024, 0.0027, 0.0031) *
    nightCore * nightWeight * nightEdgeFeather;
  color += nightAirglow;
  gl_FragColor = vec4(color, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}

uniform vec3 sunDirection;
uniform float solidBoundaryViewDot;

varying vec3 vWorldNormal;
varying vec3 vWorldPosition;

void main() {
  vec3 normal = normalize(vWorldNormal);
  vec3 viewDirection = normalize(cameraPosition - vWorldPosition);
  float viewDot = max(dot(normal, viewDirection), 0.0);
  float solarDot = dot(normal, sunDirection);
  float day = smoothstep(-0.055, 0.1, solarDot);
  float edgeFeather = smoothstep(0.002, 0.022, viewDot);
  float pathLength = clamp(
    viewDot / max(solidBoundaryViewDot, 0.0001),
    0.0,
    1.0
  );
  float surfaceFeather = 1.0 - smoothstep(
    solidBoundaryViewDot,
    solidBoundaryViewDot + 0.012,
    viewDot
  );
  float extinctionBand = edgeFeather *
    pow(pathLength, 0.68) * surfaceFeather;

  // Extinction is distinct from additive airglow: this almost-transparent
  // neutral layer gently attenuates stars or Luna seen through the
  // upper atmosphere. Optical depth grows inward toward the solid globe,
  // producing a photographic taper against Luna without painting a bright
  // ring against empty space.
  float alpha = extinctionBand * 0.17 * mix(1.0, 0.2, day);
  vec3 extinctionColor = vec3(0.002);
  gl_FragColor = vec4(extinctionColor, alpha);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}

uniform vec3 sunDirection;
uniform float intensity;

varying vec3 vWorldNormal;
varying vec3 vWorldPosition;

void main() {
  vec3 normal = normalize(vWorldNormal);
  vec3 viewDirection = normalize(cameraPosition - vWorldPosition);
  float viewDot = max(dot(normal, viewDirection), 0.0);
  float solarDot = dot(normal, sunDirection);
  float day = smoothstep(-0.16, 0.16, solarDot);

  // The wide lobe overlaps the cyan shell, then shifts continuously toward
  // cobalt as it reaches space. That overlap prevents the two atmosphere
  // shells from reading as separate, stacked bands.
  float outerFalloff = smoothstep(0.02, 0.18, viewDot) *
    (1.0 - smoothstep(0.38, 0.7, viewDot));
  float cyanTransition = smoothstep(0.025, 0.15, viewDot);
  float strength = outerFalloff * intensity * mix(0.58, 0.9, day);
  vec3 cobalt = mix(
    vec3(0.001, 0.018, 0.16),
    vec3(0.018, 0.16, 0.8),
    cyanTransition
  ) * strength;

  gl_FragColor = vec4(cobalt, 1.0);
  #include <tonemapping_fragment>
  #include <colorspace_fragment>
}

attribute float aAge;
attribute float aLife;
attribute float aSize;
attribute float aSeed;

uniform float uPixelRatio;

varying float vAlpha;
varying float vSeed;

void main() {
  float progress = clamp(aAge / max(aLife, 0.001), 0.0, 1.0);
  float fadeIn = smoothstep(0.0, 0.18, progress);
  float fadeOut = 1.0 - smoothstep(0.18, 1.0, progress);
  vAlpha = fadeIn * fadeOut;
  vSeed = aSeed;

  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  gl_PointSize = aSize * uPixelRatio * mix(1.0, 0.62, progress);
}

precision highp float;

varying float vAlpha;
varying float vSeed;

void main() {
  vec2 point = gl_PointCoord - 0.5;
  float distanceFromCenter = length(point);
  float core = 1.0 - smoothstep(0.03, 0.16, distanceFromCenter);
  float horizontalRay =
    (1.0 - smoothstep(0.0, 0.36, abs(point.x))) *
    (1.0 - smoothstep(0.0, 0.075, abs(point.y)));
  float verticalRay =
    (1.0 - smoothstep(0.0, 0.36, abs(point.y))) *
    (1.0 - smoothstep(0.0, 0.075, abs(point.x)));
  float sparkle = max(core, max(horizontalRay, verticalRay) * 0.42);
  float twinkle = mix(0.78, 1.08, fract(sin(vSeed * 437.91) * 1241.73));
  vec3 coolWhite = vec3(0.58, 0.74, 1.0);
  vec3 warmWhite = vec3(1.0, 0.78, 0.4);
  vec3 softWhite = vec3(0.88, 0.9, 0.84);
  vec3 color = mix(coolWhite, warmWhite, fract(sin(vSeed * 18.71) * 93.47));
  color = mix(color, softWhite, 0.24);

  gl_FragColor = vec4(color * sparkle * twinkle, sparkle * vAlpha * 0.56);
}

